item.aggregated_output:
{"id":"82:7/q07","question":"8. ayetteki فِيٓ أَىِّ صُورَةٍ, فَعَدَلَكَ ile nasıl ilişkilidir?","turns_on":"fī'nin ʿadalaka'ya mı yoksa sonraki rakkabaka'ya mı bağlandığı ve yöneltme anlamının ilā gerektirip gerektirmediği.","positions":[{"id":"82:7/q07/p1","position":"Düzenleme fiilini sürdürerek şeddeli okuyuşu destekler.","reasons":"Taberî, Arapçada düzenleme anlamının fī ile daha doğal söylenmesi nedeniyle şeddeli okuyuşu tercih eder. Nehhâs ve Vâhidî'nin aktardığı Ferrâ, yöneltmenin fī değil ilā aldığını söyler; Vâhidî 8. ayetin hafif fiile bağlanmasının zayıf olduğunu belirtir. Study Quran, 8. ayet 7. ayeti sürdürüyorsa şeddeli biçimin dilbilgisi bakımından daha iyi olduğunu söyler."},{"id":"82:7/q07/p2","position":"Cümle فعدلك ifadesinde biter; fī sonraki ركبك fiiline aittir.","reasons":"Nehhâs, Ferrâ'nın hafif okuyuşa yönelik itirazını reddetmek için bu bağlantıyı kullanır."}]}
{"id":"82:7/q08","question":"Rahimde biçimlenmeye ilişkin hangi anlatı bu ayetle ilişkilendirilir?","turns_on":"","positions":[{"id":"82:7/q08/p1","position":"Bir meleğin kişinin toprağını embriyoyla karıştırmasından önce üç kırk günlük aşama vardır.","reasons":"İbn Hâleveyh anlatıyı ilahî biçimlendirmeyle ilişkilendirir ve 3:6 ile 23:14'ü aktarır; eldeki alıntı anlatının ortasında kesilir."}]}
{"id":"82:7/q09","question":"Peygamber'e ait hangi azarlama bu ayetin dilini kullanır?","turns_on":"","positions":[{"id":"82:7/q09/p1","position":"Allah, Âdemoğlunu yaratıp biçimlendirdikten ve doğrulttuktan sonra onu kibir ve mal yığma yüzünden azarlar.","reasons":"Busr b. Cehhâş Peygamber'in anlatımını aktarır: kişi malını esirger ve ancak ölüm köprücük kemiklerine ulaştığında sadaka vereceğine söz verir. Mizzî, Yahyâ b. Hamza, Sevr b. Yezîd ve Abdurrahman b. Meysere üzerinden gelen destekleyici bir rivayet yolunu belirtir."}]}
{"id":"82:7/q10","question":"İnsanın yaratılması ve düzenlenmesi için hangi içsel yorumlar verilir?","turns_on":"Aktarılan iki içsel açıklama, bilgi ve imanı veya insanlığın diğer yaratılmışlarla ilişkisini vurgular.","positions":[{"id":"82:7/q10/p1","position":"Allah insan biçimini bilgiyle mükemmelleştirdi ve imanla düzenledi.","reasons":"Bursevî Cüneyd'in ifadesini aktarır."},{"id":"82:7/q10/p2","position":"Allah insanı yarattı ve onu yaratılmışların hizmetine vermeden bütün yaratılmışları onun hizmetine verdi.","reasons":"Bursevî Zünnûn'un ifadesini aktarır."}]}
{"id":"82:7/q11","question":"İnsanın yaratılışı Allah'ın cömertliğini ve rabliğini nasıl temellendirir?","turns_on":"","positions":[{"id":"82:7/q11/p1","position":"İnsanı yaratıp uygun biçime sokmak Allah'ın rabliğini ve cömertliğini gösterir; varoluşun kendisi ilk nimettir.","reasons":"Beyzâvî bu nitelemeyi rabliğin doğrulanması ve cömertliğin tezahürü sayar. Bursevî varoluşun yokluktan daha iyi olduğunu söyler; Elmalılı varoluşu bütün nimetlerin temeli sayar ve 15:29 ile 17:70 ışığında aklı ve üstünlüğü bağış olarak niteler."}]}
{"id":"82:7/q12","question":"İnsanın biçimlendirilmesi diriliş ve hesap hakkında neyi gerektirir?","turns_on":"","positions":[{"id":"82:7/q12/p1","position":"İnsanları ilk kez yaratan ve biçimlendiren onları yeniden yaratabilir ve hesaba çekecektir.","reasons":"Beyzâvî ve Bursevî ilk yaratılıştan yeniden yaratmayı çıkarır. Islâhî ilk yaratılışın dirilişi zor olmaktan çıkardığını ve insanın biçimlendirilmesindeki kudret, yaratıcılık, ihtimam, hikmet, merhamet ve adaletin amaçlı bir hayatı ve yaklaşan ödül-ceza gününü gösterdiğini söyler. Elmalılı'nın mükemmellikten muhtemel düşüş yorumu 95:5 ile ahiret hakkında uyarır."}]}
{"id":"82:7/q13","question":"İnsanın yaratılışı nasıl bir karşılık gerektirir?","turns_on":"Vurgunun ilahî biçimlendirmeden doğan yükümlülükte mi, yoksa hesap öncesindeki fırsat ve gözetimde mi olduğu.","positions":[{"id":"82:7/q13/p1","position":"Kibir, nankörlük veya inkâr yerine şükür ve saygıyla korkma gerektirir.","reasons":"Bikāî ölçülü kılanın biçimi bozabileceğini veya cezalandırabileceğini söyler. Kur'an Yolu, bedensel ve zihinsel yetilerin ve bütün nimetlerin isyanı ve inkârı nankörlük kıldığını söyler. İbn Kesîr'in Peygamber'den aktardığı rivayet, Allah'ın bağışlarından sonra kibri ve mal yığmayı azarlar. Islâhî insanın biçimlendirilmesinin amaç ve sorumluluğu ortaya koyduğunu, sınavı yerine getirmeyi reddetmenin cezayı hak ettiğini söyler."},{"id":"82:7/q13/p2","position":"Allah'ın şu an tanıdığı mühlet, kötülük yapanlara hesap öncesinde ıslah olmaları için zaman verir.","reasons":"Islâhî bu fırsattan sonra reddetmenin mazeret bırakmadığını söyler; görevlendirilmiş melekler bu arada her sözü ve eylemi kaydeder, dolayısıyla gecikme hiçbir şeyi gizlemez."}]}
{"id":"82:7/q14","question":"İnsanın dengeli yaratılışı insan tabiatı ve mertebesi hakkında neyi gerektirir?","turns_on":"Çıkarılan anlamın uyumlu insan tabiatı mı, olağanüstü yetiler mi, yoksa halifelik görevi mi olduğu.","positions":[{"id":"82:7/q14/p1","position":"Bedensel dürtüler ile düşünsel veya ruhsal algı, ilahî iradeyle amaçlanmış insan tabiatında bir arada bulunur.","reasons":"Esed bedensel ihtiyaçları ve duygusal dürtüleri düşünsel ve ruhsal algılarla birlikte ele alır ve beden ile ruh arasında içkin bir ahlaki çatışma olmadığı sonucuna varır."},{"id":"82:7/q14/p2","position":"İnsanın aklı, düşüncesi, gücü ve güzel biçimi diğer yaratılmışlardan üstünlüğünü gösterir.","reasons":"Elmalılı Ebû Ali el-Fârisî'nin açıklamasını aktarır ve 15:29 ile 17:70'i kaynak gösterir; Vâhidî de el-Fârisî'nin kendine özgü yetileri bulunan, incelikle ölçülü kılınmış insan açıklamasını aktarır."},{"id":"82:7/q14/p3","position":"İnsanlığın yaratılmışlar arasındaki orta konumu halifeliğe ve orta ümmete uygundur.","reasons":"Islâhî bu görevin yerine getirilmesini cennetin ebedî hükümranlığıyla ilişkilendirir ve 95:4'ü aktarır."}]}
{"id":"82:7/q15","question":"Bu ayet, Tekvîr'le karşılaştırıldığında İnfitâr'ın savına nasıl hizmet eder?","turns_on":"","positions":[{"id":"82:7/q15/p1","position":"İnfitâr, insanın yaratılışındaki Allah'ın yaratıcılığından, kudretinden, hikmetinden, adaletinden ve merhametinden hesaba kanıt getirir.","reasons":"Islâhî, Tekvîr'in Kur'an'ın sahihliğinden, kaynağından, vahyedilmesinden ve taşıyıcısından hareket eden akıl yürütmesini İnfitâr'ın insanın biçimlendirilmesine ilişkin işaretleriyle karşılaştırır. Biçim, üslup, anlamlar ve başlangıçtaki büyük felaket bakımından iki sûreyi birbirinin karşılığı sayar; her ikisi de binalarına güvenen ve uyarıları görmezden gelen zengin, kibirli Kureyşlilere hitap eder. Tekvîr'in Kur'anî kanıtını reddedenlerin parlak şafağı karanlık geceden ayıramadığını söyler."}]}
{"id":"82:7/q16","question":"Bu ayetin bulunduğu sûre ne zaman indirildi?","turns_on":"Sûrenin Mekke dönemi içindeki tarihlendirilmesi; not, belirleyici özel bir kanıt vermez.","positions":[{"id":"82:7/q16/p1","position":"Mekke döneminin başlarında.","reasons":"Esed bazı otoritelerin bu tarihlendirmesini aktarır."},{"id":"82:7/q16/p2","position":"Daha büyük olasılıkla Mekke'deki son vahiyler grubunda.","reasons":"Esed geç tarihlendirmeyi daha muhtemel görüş olarak aktarır."}]}
{"id":"82:7/q17","question":"Tefsirde örtülen ve bağışlanan günahlara ilişkin hangi hadis yer alır?","turns_on":"","positions":[{"id":"82:7/q17/p1","position":"Allah mümini yakınına alır, onu örter, günahlarını itiraf ettirir, ardından hayattayken onları örttüğünü ve bugün bağışladığını söyler.","reasons":"Bursevî bunu sahih bir hadis olarak aktarır; mümin bağışlanma ilanından önce helak olmaktan korkar."}]}
{"id":"82:8/q01","question":"أَىِّ burada ne ifade eder?","turns_on":"ayy'nin yalnızca ihtimaller arasından seçim mi yaptığı, yoksa bağlamsal hayreti de mi ifade ettiği.","positions":[{"id":"82:8/q01/p1","position":"Allah'ın seçtiği mümkün biçimlerden herhangi birini belirtir.","reasons":"İbn Âşûr ayy'nin aslında bir şeyi benzerlerinden ayıranın ne olduğunu sorduğunu söyler ve 80:18 ile 7:185'i aktarır; burada nekre bir ismi niteler veya ona muzaf olur. Elmalılı'nın ilk çözümlemesi onu herhangi bir biçim anlamında sıfat sayar; ikinci çözümlemesi ise şart anlamı verir."},{"id":"82:8/q01/p2","position":"Olağanüstü, mükemmelleştirilmiş biçime duyulan hayreti ifade eder.","reasons":"İbn Âşûr hayretin alışılmış bir kullanım olduğunu, mükemmelliğin kelimenin kendisinden değil bağlamdan geldiğini söyler; ortaya çıkan biçimi eksiksiz ve hayranlık uyandırıcı olarak okur. Zemahşerî ayy'de hayret anlamı duyar, ancak Semîn onun buna dayalı söz dizimine itiraz eder."}]}
{"id":"82:8/q02","question":"Ayetteki صُورَةٍ neyi ifade eder?","turns_on":"Biçimin insanlık içindeki bedensel farklılıklar, akrabaya benzerlik, mümkün hayvan biçimleri veya içsel nitelikler anlamlarından hangisini taşıdığı; bazı kaynaklar birden fazla kapsama imkân tanır.","positions":[{"id":"82:8/q02/p1","position":"Cinsiyet, yapı, boy, renk, güzellik, sağlık ve yüz hatları bakımından değişen belirli bir insan bedeni biçimi.","reasons":"Ferrâ ve Zeccâc uzun, kısa, yakışıklı veya başka türlü olmayı verir; Kuşeyrî uzuvların hikmetli düzenini ekler. İbn Kuteybe renkleri verir ve 30:22'yi aktarır. Tabersî ve Kurtubî erkek ve kadını kapsar. Elmalılı bedensel farklılıkları sağlık ve zekâya kadar genişletir. Islâhî farklı yüzlerin ve biçimlerin zahmetsiz yaratma becerisini gösterdiğini söyler."},{"id":"82:8/q02/p2","position":"Anne veya babaya, başka bir ataya veya akrabaya benzeyen bir biçim.","reasons":"Mücâhid baba, anne, amca ve dayıyı sayar; Kurtubî diğer akrabaları ekler. Peygamber'e atfedilen bir rivayet, meni rahme yerleştikten sonra Allah'ın Âdem'e kadar uzanan soy hatlarını ortaya çıkardığını söyler. İbn Kesîr uzak bir ataya ait özellik için daha sahih olan deve benzetmesini aktarır. Dürr ayrıca her ebeveynden doksan dokuz damar geldiğine ilişkin bir rivayet aktarır. Elmalılı kalıtılan özelliklerin uzak atalardan gelebileceğini söyler."},{"id":"82:8/q02/p3","position":"Allah bir kişiye hayvan veya insan olmayan başka bir biçim verebilirdi.","reasons":"Mukātil insan biçiminden başka bir biçime imkân tanır. Rivayet edilen örnekler değişir: köpek, eşek, domuz, insansı maymun veya maymun, at, hayvan ve kuş; Bikāî bilinmeyen biçimleri kapsar. İbn Atıyye bunu tehdit olarak okur; İbn Kesîr ilahî kudreti ve dik insan biçiminin lütufkâr biçimde seçilmesini vurgular; Study Quran cezalandırmayı bir ihtimal olarak sunar ve 2:65'i aktarır. Sâdık gerçekleşen en iyi insan biçimini hayvan biçimleriyle karşılaştırır."},{"id":"82:8/q02/p4","position":"İman veya itaatsizlik, saadet veya mutsuzluk, kurtuluş veya azaba mahkûmiyet gibi içsel veya ahlaki bir biçim.","reasons":"Kuşeyrî sureti sıfat, fī'yi ise ʿalā olarak okur. Study Quran iman ve itaatsizliği içsel nitelikler, saadet ve bedbahtlığı da kurtuluş ve azaba mahkûmiyet halleri olarak aktarır ve 11:105'i kaynak gösterir. Elmalılı doğruluğu ve karşıtını mümkün ahlaki özellikler arasında sayar."}]}
{"id":"82:8/q03","question":"صُورَةٍ için hangi sözlük ayrımı yapılır?","turns_on":"","positions":[{"id":"82:8/q03/p1","position":"ṣād ile ṣūra bir nesneyi içinde barındıranı ifade eder; sīn ile sūra ise dıştan kuşatır.","reasons":"Zerkeşî el-Burhân'da bu ünsüz ayrımını yapar."}]}
{"id":"82:8/q04","question":"فِىٓ kişi ile biçim arasındaki ilişkiyi nasıl tasvir eder?","turns_on":"Mekân bildiren edatın kuşatıcı bir hali mi tasvir ettiği, yoksa içsel bir yorumda ʿalā anlamına mı kaydığı.","positions":[{"id":"82:8/q04/p1","position":"Kişinin biçimini, onu tamamen niteleyen kuşatıcı bir hal olarak mecazen gösterir.","reasons":"İbn Âşûr fī'nin beraberlik anlamına geldiğini; hâl olarak yer alan suretin bir kap gibi tasvir edildiğini söyler. Kuşeyrî'nin içsel yorumu ise fī'yi ʿalā olarak açıklar."},{"id":"82:8/q04/p2","position":"Suret içsel bir sıfat anlamına geldiğinde ʿalā anlamını taşır.","reasons":"Kuşeyrî bu edat anlamını saadet, mutsuzluk, iman ve itaatsizlik için kullanır."}]}
{"id":"82:8/q05","question":"مَّا شَآءَ içindeki مَّا'nın işlevi nedir?","turns_on":"mā'nın dilbilgisel durumu ve buna göre shāʾa'nın ṣūra ve rakkabaka ile ilişkisi.","positions":[{"id":"82:8/q05/p1","position":"Mā zâit bir pekiştirme edatıdır; Allah kişiyi dilediği herhangi bir biçimde bir araya getirip oluşturmuştur.","reasons":"Ferrâ ve Zeccâc bunu bedensel farklılıklarla ilişkilendirir. Semîn shāʾa'nın ṣūra'yı nitelediğini söyler; Ebü'l-Bekā niteleme cümlesinde hazfedilmiş dönüş zamirini verir. Tabersî ve Elmalılı aynı pekiştirici çözümlemeyi sunar."},{"id":"82:8/q05/p2","position":"Mā şart anlamındadır: Allah kişiyi dilediği herhangi bir surette biçimlendirir.","reasons":"Zeccâc ve Ebû İshak şartlı açıklamayı verir. Tabersî, bu durumda Sîbeveyhi'nin kuralı uyarınca soru ifadesinin açık fiiller yerine hazfedilmiş bir yönetici fiile ihtiyaç duyduğunu söyler. Beyzâvî rakkabaka'yı cevap sayar; Semîn hazfedilmiş bir cevap da aktarır. Elmalılı'nın şartlı okuyuşu gelecekteki mümkün yeniden biçimlendirmeye ve uyarıya işaret eder; ata rivayetinin ayy veya mā'da şart anlamını desteklediğini söyler."},{"id":"82:8/q05/p3","position":"Mā, shāʾa ile kullanılan ve Allah'ın dilediği tarzı anlatan bir mastar olarak mansûbdur.","reasons":"Semîn bunu Zemahşerî'nin fī'yi ʿadalaka'ya bağlayarak güzel bir düzenleme anlamı veren çözümlemesine atfeder; Semîn bunu mā'nın üç muhtemel çözümlemesinden biri olarak verir."},{"id":"82:8/q05/p4","position":"Mā, mef'ûl-i mutlak olarak mansûb bir ilgi zamiridir: Allah seçtiği yapıyı biçimlendirmiştir.","reasons":"İbn Âşûr shāʾa'nın hazfedilmiş nesnesini “onu diledi” diye tamamlar ve 3:6'yı aktarır. Elmalılı fī'yi ʿadalaka'ya bağlayan çözümlemede mümkün bir ayrı ilgi cümlesinden söz eder."}]}
{"id":"82:8/q06","question":"فِىٓ أَىِّ صُورَةٍ ifadesini hangi fiil veya örtük unsur yönetir?","turns_on":"Edat öbeğinin bağlandığı unsur, soru anlamındaki ayy için mümkün yönetim ve önceki hafif ʿadalaka'nın fī alıp alamayacağı.","positions":[{"id":"82:8/q06/p1","position":"رَكَّبَكَ fiiline bağlanır: Allah kişiyi seçilen biçimde bir araya getirip oluşturmuştur.","reasons":"İbn Atıyye bunu çoğunluğa atfeder. Kurtubî hafif ʿadalaka yapısının fī değil ilā aldığını savunur ve Ferrâ'nın aksi bağlantıyı reddettiğini söyler. Semîn ve Ebü'l-Bekā bu çözümlemeyi verir; İbn Âşûr önceki ʿadalaka'dan sonra duraklama koyar. Elmalılı bunu geçerli okuyuşlardan biri olarak verir."},{"id":"82:8/q06/p2","position":"Önceki عَدَلَكَ fiiline bağlanarak Allah'ın kişiyi hangi biçimde ölçülü kıldığını anlatır.","reasons":"İbn Atıyye bu alternatifi aktarır. Beyzâvî bu görüştedir; Zemahşerî hayret uyandıran bir biçim anlar, ancak Semîn soru anlamındaki ayy'nin yönetici unsurundan sonra gelemeyeceğini söyleyerek itiraz eder. Elmalılı, mā shāʾa rakkabaka'nın ayrı bir ilgi cümlesi, nekreye bağlı cümle veya şart cümlesi olmasıyla bu çözümlemeyi geçerli bulur."},{"id":"82:8/q06/p3","position":"Hazfedilmiş bir unsurun yönettiği hâldir: Allah kişiyi bir biçim içinde bulunur halde bir araya getirip oluşturmuştur.","reasons":"Semîn bunu ikinci bir çözümleme olarak aktarır."},{"id":"82:8/q06/p4","position":"Önceki yaratma, ölçülü kılma ve dik hale getirme dizisine bağlanır.","reasons":"İbn Âşûr bunun “hangi surette olursa olsun” ifadesinden sonra duraklamaya imkân verdiğini söyler; diğer çözümlemesi ifadeyi rakkabaka'ya bağlar ve ʿadalaka'dan sonra duraklar."},{"id":"82:8/q06/p5","position":"Şart anlamındaki mā ile soru ifadesini hazfedilmiş bir fiil yönetmelidir.","reasons":"Tabersî Sîbeveyhi'nin kuralına başvurur: soru ifadesi kendisinden sonra gelen açık rakkabaka veya ʿadalaka tarafından yönetilemez. Semîn de takrirî bir sorunun bile yönetici unsurunun kendisinden önce bulunamayacağını söyler ve kayfa, annā ile haber bildiren kam'ı karşılaştırır. Başka bir çözümleme fī'yi shāʾa veya rakkabaka'dan birine bağlar; böylece soru ifadesi mā'nın önünde kurala uygun biçimde yer alır."}]}
{"id":"82:8/q07","question":"رَكَّبَكَ ne anlama gelir?","turns_on":"","positions":[{"id":"82:8/q07/p1","position":"Allah parçaları birleştirip seçtiği biçime uydurarak kişiyi oluşturmuştur.","reasons":"İbn Atıyye tarkīb'i birleştirme ve bir şeyi başka bir şeye ekleme olarak tanımlar; Kuşeyrî bedensel uzuvları hikmetli tasarımlarla ilişkilendirir. Islâhî yaratma fiilleri dizisini taslak çizme veya yapma, ardından mükemmelleştirme olarak okuyarak ilk ve son aşamalara işaret ettiğini belirtir. İtkān'daki rivayet bunu “sana biçim verdi” diye açıklar."}]}
{"id":"82:8/q08","question":"رَكَّبَكَ önceki cümleye söz dizimi bakımından nasıl bağlanır?","turns_on":"İfade edilmeyen bağlantının açıklama mı, yoksa hazfedilmiş bir bağlaç mı olduğu.","positions":[{"id":"82:8/q08/p1","position":"Açık bir bağlaç olmadan önceki عَدَلَكَ ifadesini açıklar.","reasons":"Beyzâvî açıklama ilişkisinin atıf yokluğunu izah ettiğini söyler. Semîn de onu fāʾ ile bağlanmış değil, açıklayıcı olarak niteler."},{"id":"82:8/q08/p2","position":"Bağlacı hazfedilmiş olarak عَدَلَكَ ile atıf ilişkisi kurar.","reasons":"Tabersî bunu pekiştirici mā çözümlemesinde belirtir."}]}
{"id":"82:8/q09","question":"رَكَّبَكَ ardından gelen كَلَّا öncesinde nasıl telaffuz edilir?","turns_on":"Ayet sınırındaki bitişik kāf harflerinin nakli ve ses bakımından ele alınması.","positions":[{"id":"82:8/q09/p1","position":"Bitişik kāf harfleri ayet sınırında idgam edilir.","reasons":"Ahfeş hangi harfin harekeli olduğuna göre idgam koşullarını verir. İbn Atıyye Hârice'nin Nâfi'den naklini aktarır. İbnü'l-Cezerî Ahvâzî'nin Ruveys'ten naklini aktarır ve al-Mabhaj'ın da bunu içerdiğini söyler; bu yer Ruveys'in ihtiyarî idgamları arasındadır."},{"id":"82:8/q09/p2","position":"İki kāf harfi idgamsız, açıkça telaffuz edilir.","reasons":"Ahfeş onları ayrı bırakma koşullarını da açıklar. İbnü'l-Cezerî, Ebü't-Tayyib ve İbn Muksim'in Temmâr üzerinden Ruveys'ten ve diğer raviler üzerinden gelen açık telaffuzu aktarır; Ruveys'ten gelen her iki telaffuz da sahihtir. Listesi 82:8–9 dahil on dört ihtiyarî idgam yerini kapsar."}]}
{"id":"82:8/q10","question":"Rivayet edilen anlatılar çocuğun benzerliği belirlenirken ne olduğunu söyler?","turns_on":"Rivayetler benzerliği açıklamak için kullanılan mekanizma ve ayrıntılar bakımından farklılaşır.","positions":[{"id":"82:8/q10/p1","position":"Meni rahme yerleştikten sonra Allah Âdem'e ulaşan ata soylarını ortaya çıkararak anne babanın ötesindeki benzerliklere imkân verir.","reasons":"Peygamber'in soru soran birine verdiği rivayet edilen cevap bu ayete başvurur. Bikāî ve Dürr'ün Mâlik b. Huveyris rivayeti, erkeğin sıvısının kadının damarları ve sinirleri boyunca yayıldığını ve Allah'ın yedinci günde ataların damarlarını topladığını ekler; diğer nakiller zamanlamayı içermez. Vâhidî rivayeti Mücâhid'in akrabaya benzerlik yorumunu desteklemek için kullanır. Tabersî'nin rivayet yolu Rızâ ve onun ataları üzerinden gelir."},{"id":"82:8/q10/p2","position":"Her ebeveynin doksan dokuz damarı vardır ve çocuk oluşurken Allah'tan onun kendilerine benzemesini isterler.","reasons":"Dürr bunu siyahi bir Ensârî yenidoğan hakkındaki rivayette aktarır."},{"id":"82:8/q10/p3","position":"Yenidoğanın beklenmedik rengi, sürüsündeki bir devenin rengi gibi, atadan gelen bir özelliği yansıtabilir.","reasons":"İbn Kesîr her iki Sahih'te bulunan Ebû Hüreyre rivayetini soy hattı benzetmesi olarak aktarır."}]}
{"id":"82:8/q11","question":"Ata soylarına ilişkin rivayetler nasıl değerlendirilir?","turns_on":"Değerlendirilen belirli nakil ve isnat.","positions":[{"id":"82:8/q11/p1","position":"Söz konusu soy rivayeti sahih olsaydı ayetin anlamını kesinleştirirdi, ancak isnadı sabit değildir veya zayıftır.","reasons":"İbn Kesîr, Ebû Saîd b. Yûnus'a göre Muṭahhar b. al-Haytham'ın metrûk olduğunu söyler ve İbn Hibbân'ın eleştirisini belirtir. İtkān aktarılan biçimini zayıf diye niteler. Vâhidî bir biçimini derecelendirmeden aktarır."},{"id":"82:8/q11/p2","position":"Aktarılan ata damarları rivayeti güvenilir ravilere veya hasen bir isnada sahiptir.","reasons":"Bikāî, Mâlik b. Huveyris'in yedinci gün anlatısının ravilerinin güvenilir olduğunu söyler; Dürr bu anlatıyı hasen isnatlı olarak niteler."}]}
{"id":"82:8/q12","question":"İkinci şahıs hitabı kime yöneliktir?","turns_on":"İkinci şahıs hitabının bireysel mi yoksa genel mi olduğu.","positions":[{"id":"82:8/q12/p1","position":"Tek bir kişiye değil, genel olarak insanlığa hitap eder.","reasons":"İbn Kuteybe 84:6'daki “Ey insan, Rabbine doğru çabalayan” ifadesiyle karşılaştırır ve hitabın belirli tek bir kişi olarak ele alınmasını reddeder."},{"id":"82:8/q12/p2","position":"Tenâsüh yorumunda belirli bir kişiye hitap olarak alınır.","reasons":"İbn Kuteybe bu yorumu yalnızca reddetmek için aktarır ve hitabın genel olduğunu açıkça belirterek itiraz eder."}]}
{"id":"82:8/q13","question":"Ayet ruhların tenâsühünü öğretir mi?","turns_on":"Tekil hitabın birbirini izleyen biçimlerdeki tek bir ruhu mu, yoksa farklı yaratılmış biçimler içindeki insanlığı mı ifade ettiği.","positions":[{"id":"82:8/q13/p1","position":"Bazıları ayetin ruhların tenâsühüne işaret ettiğini düşünür.","reasons":"İbn Kuteybe bu yorumu bazı kimselerden aktarır ve hitabın tek bir kişiye yönelik olmadığı gerekçesiyle reddeder."},{"id":"82:8/q13/p2","position":"Ayet Allah'ın insanları farklı biçimlerde oluşturmasını anlatır ve tenâsühe işaret etmez.","reasons":"İbn Kuteybe genel bir hitap ve güzellik, ten rengi ve başka yönlerden değişen insan biçimleri anlar; renk farklılıklarını 30:22 ile ilişkilendirir."}]}
{"id":"82:8/q14","question":"Kalıtılan biçim ve özelliklerin etkin sebebi nedir?","turns_on":"","positions":[{"id":"82:8/q14/p1","position":"Allah'ın iradesi, uzak atalardan gelen özellikler dahil biçimi ve kalıtılan özellikleri yönetir.","reasons":"Elmalılı kalıtımın var ve önemli olduğunu, ancak uzak ataların özelliklerinin hükmün tabiata değil Allah'a ait olduğunu gösterdiğini söyler. Tabâtabâî cömert Rabbin insanlığın en güzel biçimini ve düzenlerini yönettiğini, insanların bunlarda hiçbir payı olmadığını söyler ve 95:4'ü aktarır. Sâdık Allah'ın farklı bir biçim verebileceğini, ancak insanlığı en iyi biçimde yarattığını söyler."}]}
{"id":"82:8/q15","question":"Bu ayette insanın biçimlendirilmesi sorumluluk hakkında ne öğretir?","turns_on":"","positions":[{"id":"82:8/q15/p1","position":"Allah'ın insanları amaçlı ve zahmetsizce biçimlendirmesi onları diriltip hesaba çekme kudretini gösterir, şükre ve itaate çağırır.","reasons":"Islâhî ilk yaratılışın yeniden yaratmayı daha zor kılmadığını savunur; ilahî yaratıcılık, hikmet, merhamet ve adalet ödül ve cezayı gerektirir. İnsanın kendine özgülüğü ve halifeliği sorumluluğunu yerine getirmesini gerektirir; inkâr cezayı hak eder. Bikāî döllenme rivayetinin Allah'a daimî kulluğu temellendirdiğini ve kendine güvenmeye karşı uyardığını söyler. Elmalılı imana, şükre, itaate ve iyi amellere çağırır. Kur'an Yolu bedensel ve zihinsel bağışlara rağmen isyanı nankörlük sayar."}]}
{"id":"82:8/q16","question":"İnsan tabiatının irade edilmiş yönleri ahlaken içkin bir çatışma taşır mı?","turns_on":"","positions":[{"id":"82:8/q16/p1","position":"Hayır: Allah her ikisini de irade ettiği için beden ile ruh arasında içkin bir ahlaki çatışma yoktur.","reasons":"Esed insan tabiatının ilahî iradeyle belirlenmiş yönlerinden bu sonucu çıkarır."}]}
{"id":"82:8/q17","question":"Bu ayet İnfitâr'ın savına ve komşu ayetlerine nasıl hizmet eder?","turns_on":"Azarlamanın biçimlendirme ayetinin kendi ifadesinde mi bulunduğu, yoksa daha geniş diziden mi doğduğu.","positions":[{"id":"82:8/q17/p1","position":"İnsanın yaratılışı, dirilişe, hesaba ve gafletin azarlanmasına götüren ilahî kudret, amaç ve merhamet kanıtını sunar.","reasons":"Islâhî Tekvîr'in vahiyden hareket eden savını İnfitâr'ın yaratılıştan hareket eden savıyla karşılaştırır; suçlulara tanınan mühletin ıslaha imkân verdiğini ve kayıt meleklerinin amellerini koruduğunu söyler. Kur'an Yolu biçimlendirmeyi nankörlükle ilişkilendirir. İbn Kuteybe sonraki kallā'nın muhatabın aldanmasını reddettiğini söyler. Ancak İbn Hişâm ileri sürülen azarlamanın biçimlendirme ayetinde görünür olmadığına ve başka yerlerde de zorlama azarlama yorumlarının bulunduğuna itiraz eder."},{"id":"82:8/q17/p2","position":"Biçimlendirme ayetinin kendisi açıkça azarlama ifade etmez.","reasons":"İbn Hişâm burada, insanların ayakta duruşunda ve “sonra onu açıklamak Bize aittir” ifadesinde azarlama arayan yorumları zorlama sayar; özellikle üçüncü örnekte araya uzun bir mesafe girmiştir."}]}
{"id":"82:8/q18","question":"İnfitâr, Tekvîr ile nasıl ilişkilidir?","turns_on":"","positions":[{"id":"82:8/q18/p1","position":"Biçim, üslup, anlam ve başlangıçtaki büyük felaketi paylaşan, farklı kanıtlar geliştiren karşılık sûrelerdir.","reasons":"Islâhî her ikisinin de binalarına güvenen zengin, kibirli Kureyşlilere hitap ettiğini söyler; Tekvîr Kur'an'ın kaynağından, vahyedilmesinden ve taşıyıcısından, İnfitâr ise ilahî yaratıcılık, kudret, hikmet, adalet ve merhametten kanıt getirir."}]}
{"id":"82:8/q19","question":"İnfitâr, Mekke'deki vahiy sürecinin hangi zamanına tarihlenir?","turns_on":"Adı verilmeyen otoritelerin sûre için belirlediği kronoloji.","positions":[{"id":"82:8/q19/p1","position":"Bazı otoriteler onu Mekke döneminin başlarına yerleştirir.","reasons":"Esed bu görüşü notta savunucularının adlarını vermeden aktarır."},{"id":"82:8/q19/p2","position":"Başka otoriteler Mekke döneminin geç bir tarihini daha muhtemel görür.","reasons":"Esed bunu başkalarına göre daha muhtemel tarihlendirme olarak aktarır."}]}

{"id":"80:19/q11","question":"Gelişmekte olan ceninin çevresindeki üç karanlık nedir?","turns_on":"Üç kuşatıcı tabakanın karın, rahim ve plasenta olarak mı, yoksa farklı işlevleri olan üç zar olarak mı tanımlandığı.","positions":[{"id":"80:19/q11/p1","position":"Karın, rahim ve plasenta olabilirler.","reasons":"Bikāî bu tanımlamayı bir ihtimal olarak sunar."},{"id":"80:19/q11/p2","position":"Farklı işlevleri olan üç zardır.","reasons":"Bikāî anatomi bilginlerinin açıklamasını aktarır: plasenta cenini göbek deliği yoluyla beslerken diğer zarlar idrarı ve bedensel buharları alır."}]}
{"id":"80:19/q12","question":"Geçmiş zamanlı yaratma fiilleri yinelenen bir olayı mı anlatır?","turns_on":"","positions":[{"id":"80:19/q12/p1","position":"Evet; geçmiş zaman biçimlerine rağmen yinelenen bir olguyu anlatırlar.","reasons":"Esed bunu bir dizi olarak ele aldığı 18–22. ayetlere uygular."}]}
{"id":"80:19/q13","question":"Bu yaratma ve ölçü belirleme ne öğretir?","turns_on":"Notlar aynı dizinin farklı sonuçlarını vurgular: dirilişin kanıtı, ilahî gözetim ve ahlaki sorumluluk ya da insanın kibrine yönelik azarlama; İbn Âşûr, kibri azarlamanın odak olduğu görüşüne karşı çıkar.","positions":[{"id":"80:19/q13/p1","position":"Allah'ın insanı yeniden yaratma gücünü gösterir ve böylece dirilişi ve hesabı destekler.","reasons":"İbn Kesîr, takdir edilmiş yaratılışı Allah'ın yeniden yaratma gücünün kanıtı sayar. Bikāî, yaratılışın ve besin döngüsünün diriliş uyarısını desteklediğini söyler ve uyarma çağrısı olarak 79:45'i aktarır. İbn Âşûr, ilk yaratılıştan yeniden yaratmaya çıkarım yapar ve 50:15 ile 86:5–8'i aktarır. Islâhî, yaratılış, hayatın kaynakları, ölüm ve diriliş hakkındaki hatırlatmaların geçici kibrin içyüzünü açığa çıkardığını söyler; ölçülü dizi hesap ve karşılığı gerektirir, 36:39 ile 23:12–16 da onun aşamalarını aydınlatır. Kur'an Yolu, inkârcıları ve kuşku duyanları yokluktan sonra varoluş üzerine düşünmeye çağırır; Study Quran ilahî kudret için 18:37, 16:4, 40:67 ve 86:6–8'i aktarır."},{"id":"80:19/q13/p2","position":"Hikmetli ve iyiliksever ilahî yönetimi gösterir, şükre ve insanın sınırlarına riayete çağırır.","reasons":"İbn Âşûr, düzenli dizinin ilahî ihsanı da hatırlattığını söyler. Tabâtabâî, Allah'ın yarattığını, ölçü belirlediğini, yol gösterdiğini, öldürdüğünü, defnettiğini ve dirilttiğini, insanın ise bu yönetimin hiçbir unsuruna sahip olmadığını söyler; yiyecek bile ince bir ihtimamı ve ölçülemez merhameti gösterir ve bu konuda 14:34'ü aktarır. Zatta, sıfatlarda ve fiillerde takdir edilen ölçünün insanın aşmaması gereken sınırlar koyduğunu söyler. Bikāî, bilgi ve şerefin Yaratıcı tarafından verildiğini ve şükür gerektirdiğini belirtir. Nehhâs, itaatin insanı aşağı kökeninden yükselttiğini söyler; Islâhî, ölçülü hayat aşamalarında amaçlı inayet ve karşılık görür."},{"id":"80:19/q13/p3","position":"Yaratıcı'ya bağımlı birinin kibir ve nankörlüğünün akılsızlığını açığa çıkarır.","reasons":"Kurtubî ve Hasan mütevazı kökene işaret eder; Bikāî, verilmiş şerefi pis köken, atıklar ve ölümle karşılaştırır; Bursevî güzel biçimi bir nimet sayar; Tabâtabâî, Allah'ın gözetimini ihmal etmeyi zulüm ve nankörlük diye niteler; Islâhî, bu hatırlatmaların geçici kibrin içyüzünü açığa çıkardığını söyler. İbn Âşûr, sıvının anılmasının kibri azarlamaktan ziyade yaratılışın büyüklüğünü vurguladığını açıkça belirtir."}]}
{"id":"80:19/q14","question":"Bu pasaj çevresindeki bağlamla nasıl ilişkilidir?","turns_on":"Ayetlerin önceki pasajla tek bir bağlam oluşturup oluşturmadığı veya ayrıca rivayet edilen bir nüzul sebebine ait olup olmadığı.","positions":[{"id":"80:19/q14/p1","position":"Çevresindeki uyarıyı sürdürür: yaratılış, yiyecek, ölüm ve diriliş ilahî kudreti ve insanın bağımlılığını ortaya koyar.","reasons":"Bikāî, sûrenin uyarısını korkanlarla ilişkilendirerek 79:45'i aktarır; yaratılış ve yiyecek, kabule açık kalpleri dirilişi inkârdan arındırır. Tabâtabâî, ayetlerin önceki pasajı tek bir bağlam olarak sürdürmesine imkân tanır ve ölçü belirleme, hidayet, ölüm, defnedilme, diriliş ve yiyecek dizisini açıklar. Islâhî de yaratılışı, hayatın kaynaklarını, ölümü, dirilişi ve hesabı birbirine bağlar."},{"id":"80:19/q14/p2","position":"Bazı müfessirler bu ayetlerin ayrı bir olay üzerine indirildiğini kabul eder.","reasons":"Tabâtabâî, kesintisiz bir bağlamı mümkün görmekle birlikte bu görüşü aktarır; ayrı nüzul sebebinin daha sonra ele alındığını söyler."}]}
{"id":"82:6/q01","question":"Hitap edilen insan kimdir?","turns_on":"Tekil hitabın genel olup olmadığı, ardından gelen hesap inkârıyla sınırlandırılıp sınırlandırılmadığı veya rivayet edilen belirli bir olayla ilişkilendirilip ilişkilendirilmediği; rivayetlerde adı verilen kişi değişir.","positions":[{"id":"82:6/q01/p1","position":"Genel olarak insanlık, özellikle de itaatsizliğe aldanan herkes.","reasons":"Burhân bunu genel olarak kastedilen genel bir hitap sayar; İbn Kuteybe ve İtkān, tekil hitabın bir topluluğu kapsayabileceğini belirtir. Bursevî, bağlam her nefisten salihlere (82:5) geçtiği için bütün itaatsiz insanları kapsadığını söyler ve sonraki çoğul inkârın genel bir tekilin ardından gelebileceğini belirtir. Elmalılı, belirli bir nüzul sebebinin genel ifadeyi daraltmadığını söyler. İbn Atıyye, yoktan yaratılmış insanlığı anlatır."},{"id":"82:6/q01/p2","position":"İnkârcılar, özellikle dirilişi ve hesabı inkâr edenler.","reasons":"Taberî ve Vâhidî inkârcıları belirtir. Kurtubî ve Kur'an Yolu, dirilişi, ahireti ve hesabı inkâr edenleri belirtir. Tabâtabâî, 82:9'da devam eden inkârı aktarır ve hesabı inkâr etmenin şeriatı ve rabliği inkâr etmeyi gerektirdiğini söyler. Elmalılı, sonraki inkâra dayanıldığını aktarır. Kur'an Yolu, özel hedefin tek bir kişi veya ayrım gözetmeksizin herkes değil, bu kimseler olduğunu söyler."},{"id":"82:6/q01/p3","position":"Velîd b. Muğîre.","reasons":"Atâ bunu nüzul sebebi olarak aktarır; İbn Abbas da kaynak gösterilir. Bursevî bunu farklı isimler veren rivayetler arasında aktarır."},{"id":"82:6/q01/p4","position":"Abu al-Ashadd veya al-Ashaddayn; adı Asid veya Kilda ibn Asid ya da ibn Kilda olarak verilir.","reasons":"Rivayetlerde ad ve baba adı değişir. Mukātil onun tek gözlü ve çok güçlü olduğunu söyler, cennet kapısını tutacağı yolundaki övünmesini kaydeder ve Mekke'nin fethinde öldüğünü belirtir. Vâhidî, Peygamber'e vurduğunu ve hemen cezalandırılmadığını söyler. İbnü'l-Cevzî adların ters sıralandığı her iki biçimi kaydeder; Kurtubî ona Cumahî der. Elmalılı, Esed b. Kelede adını verir."},{"id":"82:6/q01/p5","position":"Übey b. Halef.","reasons":"İkrime, Kurtubî, Dürr, Süyûtî ve Elmalılı'da bu kimliklendirmeyi veya nüzul sebebini verir."},{"id":"82:6/q01/p6","position":"Esved b. Şerîk.","reasons":"Kelbî ve Mukātil, Peygamber'e vurduğunu ve başlangıçta cezadan kurtulduğunu söyler."},{"id":"82:6/q01/p7","position":"Useyd b. Halef.","reasons":"Dâmğânî bu adı verir."},{"id":"82:6/q01/p8","position":"Ümeyye b. Halef.","reasons":"Süheylî onun adını verir, ancak genel ifadenin başkalarına da uygulanacağını belirtir."},{"id":"82:6/q01/p9","position":"Esved b. Kelede.","reasons":"Bursevî bunu alternatif rivayetler arasında sıralar."},{"id":"82:6/q01/p10","position":"Binalarına güvenen ve uyarıları görmezden gelen zengin, kibirli Kureyşliler.","reasons":"Islâhî hem İnfitâr'ın hem Tekvîr'in muhataplarını bu şekilde tanımlar."}]}
{"id":"82:6/q02","question":"Tekil insan hitabı bir kişiden daha fazlasına nasıl uygulanabilir?","turns_on":"","positions":[{"id":"82:6/q02/p1","position":"Tekil biçim bir topluluğa veya genel anlamda insana hitap edebilir.","reasons":"İbn Kuteybe 84:6 ve 39:8 ile karşılaştırır. İtkān da topluluğa gönderme yapıldığını belirtir. Bursevî, genel bir tekilin ardından çoğul bir suçlamanın gelebileceğini, tıpkı bir kabile mensubunun eyleminin kabileye atfedilebilmesi gibi, açıklar."}]}
{"id":"82:6/q03","question":"Günahkâra neden insan diye hitap edilir?","turns_on":"","positions":[{"id":"82:6/q03/p1","position":"İnsan tabiatı ve yaratılışının kendisi nankörlüğe karşı tanıklık eder.","reasons":"Tabâtabâî, kişinin insani niteliklerinin birlikte onun aleyhinde delile dönüştüğünü söyler. İbn Atıyye, yoktan yaratılmış birinin nasıl itaatsizlik edebileceğini, Allah'a ortak koşabileceğini veya inkâr edebileceğini sorar."}]}
{"id":"82:6/q04","question":"Yaygın ifadede mā nasıl çözümlenir?","turns_on":"","positions":[{"id":"82:6/q04/p1","position":"Özne olarak merfû durumdaki bir soru ismidir; ikinci şahıs zamir eki gharra fiilinin nesnesidir.","reasons":"Nehhâs mā'yı tam bir isim sayar; Semîn yaygın üç harfli okuyuşu ve onun özne işlevini belirtir."}]}
{"id":"82:6/q05","question":"mā gharraka nasıl okunur ve çözümlenir?","turns_on":"mā'nın olağan bir soru mu yoksa ünlem mi olduğu ve hemzeli biçimin sebep bildirme, soru veya şaşkınlık mı ifade ettiği.","positions":[{"id":"82:6/q05/p1","position":"Yaygın okuyuş, üç harfli gharraka fiiliyle soru anlamındaki mā'dır; ancak şaşkınlık da ifade edebilir.","reasons":"Semîn yaygın üç harfli biçimi ve merfû durumdaki soru mā'sını kaydeder. Bikāî, meşhur okuyuşun sorunun yanı sıra şaşkınlık da taşıdığını söyler."},{"id":"82:6/q05/p2","position":"Saîd b. Cübeyr ve A'meş hemzeli mā agharraka biçimini okur; bu okuyuş, aldanmaya neyin sebep olduğunu sorabilir veya insanın ne kadar aldanmış ya da gaflet içinde olduğuna ilişkin bir ünlem olabilir.","reasons":"İbn Cinnî, uzatılmış ünlem mā'sını aktarır, okuyuşu 2:175 ile ve 20:96'daki gibi hazfedilmiş iki tamlayan benzetmesiyle ilişkilendirir; ayrıca sebep bildiren bir soru anlamına da imkân tanır. gharra al-rajul ifadesini gaflete düşmek diye açıklar. Tabersî ünlemi ghirr veya gharara kökünden türetir; ghurur kökünden türetme de mümkündür, ancak kuralsızdır. Burhân ve İtkān bunu 2:175 ile 80:17'nin yanında Kur'an'daki üçüncü nadir ünlem biçimi olarak sıralar. Bikāî hemzeyi soru anlamında alarak “O seni aldattı mı?” diye açıklar."}]}
{"id":"82:6/q06","question":"Allah hakkında aldanmak ne anlama gelir?","turns_on":"Notlar, aldatıcı ayartma ve sahte güvenceyi, gaflet ifade eden muhtemel bir sözlük kökeninden ayırır.","positions":[{"id":"82:6/q06/p1","position":"Allah'ın hakkını ihmal edip gerçek cezadan güvende olduğuna dair sahte bir hisse kapılarak bâtıla ayartılmak.","reasons":"Zeccâc ve Vâhidî ihmale ayartılmayı anlatır; Vâhidî 35:5'teki sahte güvenceyle karşılaştırır. Begavî yükümlülüklerin terk edilmesini ekler. Cüşemî ghurur'u korkulması gereken şeyden güvende olduğunun bilgisizce sanılması olarak tanımlar; Bursevî tehlikenin gerçekliğini koruduğunu söyler. Kuşeyrî ve Elmalılı bunu itaatsizliğe uygular. Bikāî kötü bir ameli iyi görmeyi veya kesin bağışlanacağını sanmayı ekler. Tabersî'de Hâris b. Hillize'nin beyti gharur kullanımını örnekler."},{"id":"82:6/q06/p2","position":"Gaflete düşmek veya bilgisiz olmak anlamına gelebilir.","reasons":"İbn Cinnî, gharra al-rajul, fahuwa ghārr ifadesini adamın gaflete düşmesi diye açıklar; Tabersî ünlem okuyuşu için ghirr ve gharara köklerini önerir."}]}
{"id":"82:6/q07","question":"İnsanı ne aldattı?","turns_on":"Rivayetler farklı doğrudan sebepler sunar: şeytan, bilgisizlik, ilahî mühlet, örtme veya bağışlar, dünya hayatı ve içsel dikkat dağılması; Elmalılı bunların birkaçını bilgisizlik başlığı altında toplar.","positions":[{"id":"82:6/q07/p1","position":"İnsan üzerinde yetki verilmiş düşman olan şeytan onu aldattı.","reasons":"Taberî ve Katâde şeytanı tayin edilmiş düşman olarak niteler; Hasan ona kötü bir şeytan der. Beyzâvî ve Bursevî, şeytanın ilahî cömertliğin günah işlemeye izin verdiği yönündeki güvencesini anlatır. Elmalılı bunu şeytanın süslemesi olarak niteler ve 57:14 ile karşılaştırır, ardından buna kapılmanın bilgisizliğe dayandığını söyler."},{"id":"82:6/q07/p2","position":"Bilgisizlik veya akılsızlık onu aldattı.","reasons":"Peygamber'e atfedilen rivayetlerde bu cevap verilir; Ömer insanın 33:72'deki bilgisizliğini kaynak gösterir; İbn Ömer, İbn Abbas, Rebî, Hasan ve Ömer'den de benzer rivayetler aktarılır. Tüsterî'de Ömer b. Vâsıl bunu Allah'ın korumasından uzaklaşmadaki bilgisizlik olarak niteler. Elmalılı, korku bilgiyle arttığı için (35:28) bu açıklamayı tercih eder; ertelenmiş ceza, örtme ve şeytanın süslemesi de bilgisizliğe indirgenir."},{"id":"82:6/q07/p3","position":"Allah'ın hilmi ve cezayı ertelemesi günahkârı güvende olduğunu sanmaya yöneltti.","reasons":"Mukātil, Begavî, Kurtubî ve Elmalılı bunu cezanın hemen gelmemesine bağlar. Kuşeyrî ilahî mühleti de kapsar; İbnü's-Semmâk'ın şiiri ve Ebû Bekir b. Tâhir'in şiiri, uzayan mühletin kötülük yapma cesaretini artırdığı konusunda uyarır. Ali'nin hizmetkârı efendisinin hilmine güveniyordu ve bunu söyledikten sonra azat edildi. Islâhî, mühletin ıslah için verildiğini, ancak suçluların bunu yanlış yorumladığını söyler."},{"id":"82:6/q07/p4","position":"Allah'ın günahları örtmesi veya indirdiği perdeler onu aldattı.","reasons":"Sa'lebî'deki şair örtmeyi mühletle eşleştirir. Fudayl'ın tasavvur ettiği cevap indirilmiş perdeleri anar; Kurtubî karim'in örten kimse anlamına gelebileceğini söyler. Zünnûn, perde altında yaşayanların çoğu zaman aldatıldıklarının farkına varmadığı konusunda uyarır; Ali, örtmenin ve nimetlerin insanları yavaş yavaş kendine çektiği konusunda uyarır. Elmalılı örtmeye güvenmeyi bilgisizliğin bir biçimi sayar."},{"id":"82:6/q07/p5","position":"Allah'ın cömertliği, affı ve lütfu günahkârı cesaretlendirdi.","reasons":"Verrâk doğrudan “Kerîm'in cömertliği” cevabını verir; işârî yorumcular bu cevabı al-Karim sıfatından çıkarır. Mansûr Allah'ın lütuf ve affını anar; Kuşeyrî gören ama örten, cezalandırabilecek ama erteleyen bir Allah tasvir eder. İbn Atıyye bu sıfatta günahkâr müminlere yönelik ilahî iyiliği görür. Bikāî, Verrâk'ın hilmi de eklediğini aktarır. İbn Kesîr ve Elmalılı sıfatı bu cevaba dayanak yapmayı reddeder."},{"id":"82:6/q07/p6","position":"Allah'ın yumuşak davranması ve önceki veya süregelen iyilikleri onu aldattı.","reasons":"Nasr ibn Maghlis ve Süddî yumuşak davranmayı belirtir; Yahyâ b. Muâz geçmiş ve şimdiki nimetlere işaret eder. Ali, nimetlerin insanı yavaş yavaş kendine çekebileceği konusunda uyarır."},{"id":"82:6/q07/p7","position":"Dünya hayatı ve şeytan birlikte onu aldatır.","reasons":"Study Quran ikisini de belirtir ve 31:33 ile 35:5'i aktarır."},{"id":"82:6/q07/p8","position":"Servet, kibir ve uzun mühlet günahkârı aldatır.","reasons":"Ebû Bekir b. Tâhir'in beyti, bunların onu sonuçlardan korkmaksızın Allah'ın karşısına çıkardığını söyler."},{"id":"82:6/q07/p9","position":"Allah dışındaki herhangi bir şeyin kalbe girip onu Allah'tan koparması kişiyi aldatır.","reasons":"Tüsterî aldanmayı, ilahî yumuşaklık ve cömertliğe rağmen kalbi örten bir perdeyle ilişkilendirir."}]}
{"id":"82:6/q08","question":"Sorunun kendisi ne işlev görür?","turns_on":"Sorunun öncelikle kınayıp uyarması mı, aldanmayı yasaklaması mı, yoksa ilahî cömertlik cevabını çağrıştırması mı; bazı yorumlar ünleme de imkân tanır.","positions":[{"id":"82:6/q08/p1","position":"Kişiyi itaatsizlik, inkâr ve nankörlük yüzünden azarlar ve tehdit eder.","reasons":"İbn Atıyye yoktan yaratılışı hatırlatır. Beyzâvî, Allah'ın cömert diye anılmasının yersiz güveni önlemesi gerektiğini söyler. İbn Kesîr bunu açıkça tehdit sayar ve cevap olarak ima edilen bir mazereti reddeder; Tabâtabâî nimet veren Rabbe şükretmemenin mazereti olmadığını söyler. Elmalılı'ya göre sûrenin bağlamı uyarıdır; Esed hiç kimsenin fitneden bütünüyle korunmadığını söyleyerek 8:25 ve 82:9'daki cevapla karşılaştırır."},{"id":"82:6/q08/p2","position":"Yasaklama işlevi görür: Seni hiçbir şey aldatmasın.","reasons":"Burhân, “Düşünmez misiniz?” ifadesinin “Düşünün” anlamına gelmesi gibi, sorunun emir işlevi görebileceğine ilişkin genel ilkeyi verir. İtkān insanlardan ziyade Allah'tan korkmaya yönelten yasaklayıcı sorularla karşılaştırır."},{"id":"82:6/q08/p3","position":"İfadesi, kişiyi ilahî cömertliğin aldattığı cevabını vermeye yöneltir.","reasons":"İşârî yorumcular ve Tabersî cevabı al-Karim sıfatından çıkarır; Kuşeyrî yinelenen cömertlikle cesaretlenen günahkârı sahneleyerek anlatır. İbn Kesîr bu çıkarımı zayıf bularak, Elmalılı ise sûrenin uyarıcı üslubuna aykırı olduğu için reddeder."},{"id":"82:6/q08/p4","position":"Kişinin ne kadar aldanmış olduğuna ilişkin şaşkınlık da ifade eder.","reasons":"Bikāî yaygın okuyuşta bile şaşkınlık duyar. Saîd b. Cübeyr'in hemzeli okuyuşu Burhân ve İtkān'da daha açık bir ünlem olarak verilir."}]}
{"id":"82:6/q09","question":"Allah'ın “Rabbin” diye anılması ne katar?","turns_on":"","positions":[{"id":"82:6/q09/p1","position":"Allah'ın gözetimini ve yönetici rabliğini hatırlatarak O'nun ihsanına karşı isyanı özellikle çirkin kılar.","reasons":"Bikāî, ilahî gözetimin Allah'ın şeriatına uyma amacını hatırlatması gerektiğini söyler. Tabâtabâî, yöneten Rabbin nimetler yağdırdığını ve şükrü hak ettiğini, isyanın da cezayı hak ettiğini söyler. Tabersî O'nu kişinin Yaratıcısı diye niteler ve aldanan kişinin bâtılı izleyip O'na itaatsizlik ettiğini söyler. Kur'an Yolu rabb ile karim'i Allah'ın lütufkâr cemal sıfatları arasında birlikte ele alır."}]}
{"id":"82:6/q10","question":"al-Karim burada ne anlama gelir?","turns_on":"Açıklamalar cömertliğin farklı eylemlerini vurgular: af ve örtme, karşılıksız bağış, orantısız mükâfat veya genel ihsan örüntüsü.","positions":[{"id":"82:6/q10/p1","position":"Bağışlayan, affeden ve kusurları örten.","reasons":"İbn Kuteybe bağışlamayı asaletle ilişkilendirir; İbnü'l-Cevzî bağışlayıcı veya cömert anlamlarını aktarır. Kurtubî, Fudayl'ın “indirilmiş perdeler” ifadesini karim'in örten kimse anlamıyla ilişkilendirir."},{"id":"82:6/q10/p2","position":"Çıkar gözetmeden veren, gerekeni ve fazlasını sağlayıp kendisine borçlu olunanı talep etmeyen, sırf iyilik eden.","reasons":"Tabersî şu iki tanımı verir: kazanç sağlamayı veya zararı savuşturmayı amaçlamamak ve kendi hakkını istemeden yükümlülüğünün ötesinde vermek. Tabâtabâî de Allah'ın yarar veya karşılık gözetmediğini, haksızlığa tahammül ettiğini ve bilgisizlikten doğan günahları bağışladığını söyler."},{"id":"82:6/q10/p3","position":"Azı kabul edip çoğunu veren, hatta günahları iyiliklere dönüştüren.","reasons":"Tabersî kısa tanımı, ardından günahları iyiliklere dönüştürme şeklindeki daha güçlü işareti verir."},{"id":"82:6/q10/p4","position":"Gücü yettiğinde affeden, sözlerini yerine getiren, bolca veren, kendisine başvuranları koruyan ve onlara yumuşakça, doğrudan muamele eden.","reasons":"Bikāî'nin aktardığı Gazâlî, böyle birinin başkalarının başvuran kişiyi reddetmesine razı olmadığını, bütün alacaklarını tahsil etmeden öğüt verdiğini ve aracıya ihtiyaç duymadığını da söyler."},{"id":"82:6/q10/p5","position":"Lütufkâr ilahî cemal sıfatı.","reasons":"Kur'an Yolu, Allah'ın kullarına yönelik lütufkârlığını ifade eden adlar olarak karim ile rabb'i eşleştirir."}]}
{"id":"82:6/q11","question":"Rab neden al-Karim diye anılır ve O'nun cömertliği nasıl bir karşılık doğurmalıdır?","turns_on":"Sıfatın cömertliğe güvenmeyi mazeret olarak mı sunduğu, yoksa ahlaki kınamayı mı keskinleştirdiği; İbn Kesîr ve Elmalılı ilk çıkarımı açıkça reddeder.","positions":[{"id":"82:6/q11/p1","position":"O'nun cömertliği azarı ağırlaştırır ve şükre, saygıyla korkmaya, imana ve itaate yol açmalıdır.","reasons":"Beyzâvî, Bikāî, Bursevî ve Elmalılı, cömertliğin kötülük yapanları ihmal etmeyi veya itaat edenlerle etmeyenleri bir tutmayı gerektirdiğini reddeder; Bursevî ihmalin mağdurlara haksızlık olacağını ekler ve 15:49-50'yi aktarır. Bikāî, soylu bir iyilik sahibinin hilim sahibi ama heybetli olduğunu söyler. İbn Kesîr, cömertliğe çirkin eylemlerle karşılık verilmemesi gerektiğini söyler. Elmalılı, hikmetle birleşen cömertliğin “serbestçe günah işle” çıkarımını yanlış bir kıyas kıldığını söyler, 35:5 ile karşılaştırır ve müminlerdeki utanç ve pişmanlığı belirtir. Tabâtabâî, verenin karşılık beklemediği yerde nankörlüğün daha ağır olduğunu söyler. Ali'nin, hizmetkârların kötü edebinin efendinin terbiyesini yansıttığına ilişkin sözü ahlaki benzetmeyi destekler."},{"id":"82:6/q11/p2","position":"Sıfat, günahkârın Kerîm'in cömertliğinin kendisini aldattığı cevabını çağrıştırır.","reasons":"İşârî yorumcular ve Tabersî seçilen sıfatın bu cevabı ima ettiğini söyler; İbn Atıyye bunu günahkâr müminlere gösterilen iyilikle ilişkilendirir. Elmalılı uyarı bağlamının buna izin vermediğini söyler; İbn Kesîr çıkarımı zayıf bulur."}]}
{"id":"82:6/q12","question":"Nüzul sebebi rivayetlerinde Peygamber'e vuran suçluya ne oldu?","turns_on":"Rivayetler yalnızca cezanın gecikmesini belirtmeleri veya Peygamber'in hemen verdiği karşılığı ve serbest bırakmayı anlatmaları bakımından farklılaşır.","positions":[{"id":"82:6/q12/p1","position":"Peygamber'e vurdu ve hemen cezalandırılmadı; bu da ayetin nüzulüne yol açtı.","reasons":"Vâhidî bunu Abu al-Ashaddayn'e, Begavî ve İbn Kesîr ise Esved b. Şerîk'e bağlar. Elmalılı olayı aktarır, ancak adı kesinleştirmez."},{"id":"82:6/q12/p2","position":"Peygamber'e vurduktan sonra adam yere serildi, eman istedi, ona zarar vermeyeceğine söz verdi ve serbest bırakıldı.","reasons":"Bursevî, Zahrat al-Riyad'da başın tepesine indirilen darbeyi ve sonraki karşılaşmayı belirten bir rivayet aktarır."}]}
{"id":"82:6/q13","question":"Bu ayet dirilişteki hangi buluşmayı ve soruları akla getirir?","turns_on":"","positions":[{"id":"82:6/q13/p1","position":"Her kişi Allah'la tek başına karşılaşır ve kendisini neyin aldattığı, bilgisini nasıl kullandığı ve elçilere nasıl karşılık verdiği sorulur.","reasons":"İbn Mesud'un rivayeti Sa'lebî, Begavî, Tabersî ve Kurtubî'de yer alır; İbn Kesîr elçiler hakkındaki soruyu içeren bağlantılı bir hadisi aktarır."}]}
{"id":"82:6/q14","question":"İnsanı Allah'tan içsel olarak ne perdeler?","turns_on":"İçsel açıklamalar ya dikkati başka yöne çeken bir unsuru ya da ilahî korumayı terk etmeyi belirtir.","positions":[{"id":"82:6/q14/p1","position":"Allah dışındaki herhangi bir şeyin kalbe girmesi onu Allah'tan koparır.","reasons":"Tüsterî, müminin kalbinin kula en yakın olduğunu ve yabancı bir varlığın ilahî yumuşaklık ve cömertliğe rağmen perdeye dönüştüğünü söyler. Allah'ı kalple müşahede etmek kişiyi başka her şeyden uzaklaştırır."},{"id":"82:6/q14/p2","position":"Allah'ın korumasından bilgisizce ayrılmak kulu aldatır.","reasons":"Ömer b. Vâsıl ayeti okurken bu cevabı verir."}]}
{"id":"82:6/q15","question":"Kul bu hitaba karşılık Allah'la ilişkisini nasıl yaşamalıdır?","turns_on":"Notlar, davranışları dikkatle gözetme ve bağımlılığını kabul ederek dayanma şeklindeki birbirini tamamlayan uygulamaları anlatır.","positions":[{"id":"82:6/q15/p1","position":"Allah bilinciyle kalbi korumalı ve O'nun gözetimi altında amellerde sebat etmelidir.","reasons":"Tüsterî, kalbi Allah'a teslim etmenin O'nun uzuvları yönetip doğrultmasını sağladığını; kalbin tanıklığının uzuvların ne kadar özenle korunduğunu yansıttığını söyler. Yaratıcının nerede olurlarsa olsunlar yaratılmışlarla birlikte olduğunun bilincine çağırır."},{"id":"82:6/q15/p2","position":"Allah'ın rızasını aramalı, ihtiyaçlarını O'na sunmalı ve kendi zayıflığını kabul ederek O'na dayanmalıdır.","reasons":"Tüsterî, Allah'ın hilmiyle hoşnutluk verdiğini söyler, O'nun kapısında kalmaya çağırır ve insanın bilgisizliği, zayıflığı ve acizliğini Allah'ın ilmi, gücü ve kudretiyle karşılaştırır; böyle bir dayanma havayı, açık alanı, yeri ve göğü birbirine eşit kılar."}]}
{"id":"82:6/q16","question":"Allah'a atfedilen bir ünlem şaşkınlık ifade edebilir mi?","turns_on":"Şaşkınlığın gizli bir sebebi bilmemeyi gerektirip gerektirmediği ve ilahî dilin dinleyicilerin deneyimine nasıl gönderme yapabileceği.","positions":[{"id":"82:6/q16/p1","position":"Gizli bir sebep veya bir şeyin Allah'ı yücelttiğini ima ediyorsa Allah karşısında gerçek anlamda şaşkınlık kabul edilmez.","reasons":"Burhân, ezelî ilahî sıfatlardan hareket eden bu itirazı aktarır."},{"id":"82:6/q16/p2","position":"Allah'ın büyüklüğünün bir sebebi olduğunu ima etmeden yüceltme amacıyla hayret bildiren dile izin verilir.","reasons":"Burhân, ibadet edenlerin Allah'ın kudretine inanmasının buna imkân verdiği görüşünü aktarır ve O'nun uzağı yaklaştırması hakkında bir şiir nakleder. Başka âlimler, şaşkınlığın başka bir fail gerektirmeden meselenin kendisini yücelttiğini söyler; bir sebep yalnızca bize gizli olabilir."},{"id":"82:6/q16/p3","position":"İlahî ünlem, dinleyicilerin bakış açısından hayrete değer olan ve Allah'ın bildiği şeyi anlatır.","reasons":"Burhân bu görüşü tercih eder; âlimler de ilahî ünlem, dua ve umudu benzer biçimde dinleyici açısından yorumlar. Sîbeveyhi, 20:44'ü Mûsâ ve Hârûn'un kendi umutlarına göre hareket etmesi olarak açıklar; Ibn al-Da'i bu açıklamayı över."}]}
{"id":"82:6/q17","question":"Bu uyarı çevresindeki pasajla nasıl uyuşur?","turns_on":"Kaynaklar farklı bağlantıları vurgular: dirilişten inkâra giden dizi, yaratılıştan çıkarılan kanıt veya başka bir yerdeki paralel uyarı.","positions":[{"id":"82:6/q17/p1","position":"Dirilişin ilanı uyarıya ve akla dayalı bir çağrıya götürür; ardından kişinin hesabı inkârı açığa çıkarılır.","reasons":"Elmalılı, pasajın dirilişten düşünmeye geçtiğini söyler. Tabâtabâî 82:9'u inkârcıyı belirleyen ayet olarak okur; Esed bunun cevabı verdiğini söyler ve 8:25'teki geniş kapsamlı fitne tehlikesiyle karşılaştırır. Study Quran 82:6–12'nin ahiret günü hakkında kınayıp uyardığını söyler. Islâhî, mevcut mühletin ıslah için zaman tanıdığını, kayıt meleklerinin ise hiçbir şeyin gizli kalmamasını sağladığını söyler."},{"id":"82:6/q17/p2","position":"İnsanların yaratılması ve biçimlendirilmesi Allah'ın kudretini, hikmetini, merhametini ve adaletini göstererek dirilişi ve hesabı kesin ve amaçlı kılar.","reasons":"Islâhî, yeniden yaratmanın ilk yaratılıştan daha zor olamayacağını ve insanın biçimlendirilmesindeki işaretlerin ödül ve ceza gününü gerektirdiğini savunur. Tabâtabâî rablik ve cömertliği nankörlüğe karşı delil sayar."},{"id":"82:6/q17/p3","position":"Uyarı, Allah hakkında aldanmama yönündeki Kur'anî ikazı tekrarlar.","reasons":"Elmalılı öğretiyi 35:5 ile özdeş sayar; Islâhî başka bir yerde bir uyarıyı açıkça 82:6 ile ilişkilendirir."}]}
{"id":"82:6/q18","question":"İnfitâr, Tekvîr ile nasıl ilişkilidir?","turns_on":"","positions":[{"id":"82:6/q18/p1","position":"Biçim, üslup, anlam ve başlangıçtaki felaket bakımından birbirinin karşılığıdırlar, ancak İnfitâr başlıca yaratılıştan ve ilahî adaletten kanıt getirir.","reasons":"Islâhî her ikisinin de kibirli zengin Kureyşlilere hitap ettiğini söyler. Tekvîr Kur'an'ın sahihliği, kaynağı, vahyedilmesi ve taşıyıcısından kanıt getirir; inkârcılar şafağı geceden ayıramaz. İnfitâr ise Allah'ın yaratma kudreti, hikmeti, adaleti ve merhametinden yaklaşan hesaba kanıt getirir."}]}
{"id":"82:6/q19","question":"Kur'an başka nerede bir ayete “Ey insan” diye başlar?","turns_on":"","positions":[{"id":"82:6/q19/p1","position":"İki ayet böyle başlar: cömert Rab hakkındaki bu soru ve Rabbe doğru çabalamayı anlatan 84:6.","reasons":"Burhân bu iki başlangıcı sayar; İbn Kuteybe de tekil hitabın topluluğu kapsamasını ele alırken 84:6'yı aktarır."}]}
{"id":"82:6/q20","question":"Sûre ne zaman indirildi?","turns_on":"Aktarılan otoriteler, sûrenin Mekke'de erken mi yoksa geç dönemde mi indirildiği konusunda farklı görüştedir.","positions":[{"id":"82:6/q20/p1","position":"Bazı otoriteler onu Mekke döneminin başlarına yerleştirir.","reasons":"Esed bu tarihlendirmeyi aktarır."},{"id":"82:6/q20/p2","position":"Başkaları, onun Mekke'deki son vahiyler arasında olmasını daha muhtemel görür.","reasons":"Esed bu geç tarihlendirmeyi daha muhtemel olarak aktarır."}]}
{"id":"82:7/q01","question":"ٱلَّذِى dilbilgisi bakımından önceki ayete nasıl bağlanır?","turns_on":"İlgi zamirli ifadenin önceki yapıyı mı sürdürdüğü, yoksa bağımsız bir yapı mı başlattığı.","positions":[{"id":"82:7/q01/p1","position":"Önceki ifadeyi bedel, atf-ı beyan veya sıfat olarak izler.","reasons":"Semîn bu üç bağlantılı çözümlemeyi sıralar."},{"id":"82:7/q01/p2","position":"Merfû veya mansûb durumda bağımsızdır.","reasons":"Semîn bağımsız kullanım için her iki irap ihtimalini de verir."}]}
{"id":"82:7/q02","question":"خَلَقَكَ Allah'ın ne yaptığını söyler?","turns_on":"","positions":[{"id":"82:7/q02/p1","position":"Allah, insanı ilk olarak yoktan veya onu biçimlendirmeden önce bir damladan var etti.","reasons":"Vâhidî ve Tabersî bir damladan işiten, gören bir kişiye dönüşmeyi anlatır; Kurtubî bunun rahimde olduğunu belirtir ve çift uzuvları sayar. Elmalılı yaratmanın biçim verme, dengeleme, şekillendirme ve birleştirmeden önce geldiğini söyler; Islâhî yaratma sözcüklerinde ilk ve son aşamaları görür. Mukātil yaratma, ölçülü kılma ve dik hale getirme dizisini belirtir."}]}
{"id":"82:7/q03","question":"فَسَوَّىٰكَ neyi anlatır?","turns_on":"Biçimlendirmenin bedensel işlev, aşamalı olgunlaşma, ölçüde denklik veya her kişinin kendine özgü donanımı anlamlarından hangisini taşıdığı.","positions":[{"id":"82:7/q03/p1","position":"Allah, organları ve yetileri işlevlerine uygun, sağlıklı ve düzenli bir beden şekillendirdi.","reasons":"Vâhidî ve Tabersî embriyonik kökenin ardından işitme ve görmeyi belirtir. Beyzâvî işlevlerine hazır, sağlıklı ve ölçülü organlardan söz eder; Bursevî kavrama, yürüme ve görmeyi sayar. Bikāî her parçanın amaçlanan yararını, mizacını ve yapısını vurgular. Study Quran parçaları ve yetileri sağlıklı ve işlevsel olarak niteler; Kuşeyrî bu uygunluğu hikmetli sayar ve güzellik ile boydaki farklılıkları belirtir."},{"id":"82:7/q03/p2","position":"Allah insanı olgunlaşıp ruhu almaya elverişli hale gelene kadar aşamalar boyunca geliştirdi.","reasons":"Elmalılı bedenin, uzuvların ve yetilerin mükemmelleştirilip düzenlenmesini kapsar ve 18:37'yi aktarır; Islâhî sözcüklerin yapma veya taslak çizme ve yaratmadan mükemmelleştirmeye ilerlediğini, ilk ve son aşamalara işaret ettiğini söyler."},{"id":"82:7/q03/p3","position":"Taswiya, bir şeyi dıştan veya içten denk bir ölçüye getirmek demektir.","reasons":"Cüşemî ölçü belirleme anlamını verir ve hem bedensel biçime hem iç karaktere imkân tanır."},{"id":"82:7/q03/p4","position":"Allah her kişiyi o kişinin hayatına ve çevresine uygun nitelik ve yetilerle donattı.","reasons":"Esed yalnızca genel bir bedensel kalıbı değil, kişiye özgü uygunluğu belirtir."}]}
{"id":"82:7/q04","question":"Bitişik kāf sesleri idgam edilebilir mi?","turns_on":"","positions":[{"id":"82:7/q04/p1","position":"Belirtilen hareke koşullarına göre bitişik özdeş kāf ünsüzleri idgam edilebilir veya ayrı bırakılabilir.","reasons":"Ahfeş idgamı açıklar ve durumları birinci veya ikinci harfin harekeli olmasına göre ayırır."}]}
{"id":"82:7/q05","question":"فَعَدَلَكَ nasıl okunur?","turns_on":"Dāl'in şeddeli mi yoksa hafif mi olduğu ve sonraki ayetteki fī'nin yöneltme anlamına bağlanıp bağlanamayacağı; her iki okuyuş da aktarılmıştır.","positions":[{"id":"82:7/q05/p1","position":"Şeddeli dāl ile, fa-ʿaddalaka, II. bâb olarak okunur.","reasons":"Taberî Medineli, Mekkeli, Şamlı ve Basralı kıraat imamlarını sayar; Nehhâs aynı görüştedir. Cüşemî İbn Kesîr, Ebû Amr, İbn Âmir ve Ya'kūb'u sayar. Sa'lebî, Begavî, Kurtubî, İbn Atıyye, Semîn, İbnü'l-Cezerî ve Dürr diğer kıraat imamlarının veya çoğunluğun bu okuyuşunu aktarır; İbn Atıyye, ravilerin Peygamber'in hilali gördüğünde söylediği sözde dāl'i şeddeli okuduğu konusunda hemfikir olduğunu söyler; Dürr, Hâkim'in sahih saydığı, Peygamber'in şeddeli okuyuşuna ilişkin Ebû Hüreyre rivayetini aktarır. QIRAAT-ER kapsamlı düzenleme, düzeltme veya orantılı ayarlamayı II. bâbın anlamları olarak belirtir. Ahfeş ve İbn Hâleveyh şeddeli biçimin anlamını açıklar; Zeccâc her iki telaffuzu aktarır. Taberî ikisini de sahih kabul eder, ancak Arapçada düzenleme anlamı fī ile daha kolay birleştiği için şeddeli biçimi tercih eder. Sa'lebî'ye göre Ferrâ ve Ebû Ubeyd 95:4'ü aktararak bunu tercih eder; Vâhidî onların tercihini ve Ferrâ'nın yöneltme anlamıyla fī kullanımına itirazını aktarır. Cüşemî de Ferrâ'nın tercihini aktarır. Kurtubî, Ebû Ubeyd ve Ebû Hâtim'in 95:4 ile bu biçimi seçtiğini söyler. Study Quran, 8. ayet 7. ayeti sürdürüyorsa bu biçimi tercih eder."},{"id":"82:7/q05/p2","position":"Hafif dāl ile, fa-ʿadalaka, I. bâb olarak okunur.","reasons":"Ahfeş ve İbn Kuteybe hafif biçimi aktarır. Taberî, Nehhâs, Sa'lebî, Vâhidî, Begavî, İbn Atıyye, Tabersî, Semîn, İbnü'l-Cezerî ve Kurtubî Kûfeli kıraat imamlarını belirtir; Cüşemî ayrıca Ebû Cafer, Âsım, Hamza ve Kisâî'yi sayar. Taberî bu yerleşik okuyuşu da kabul eder. Nehhâs, Ferrâ'nın dilbilgisel itirazını reddeder: fī, rakkabaka ile kurulan sonraki cümleyi başlatır. Vâhidî'nin aktardığı Ebû Ali hafif biçime itirazı ortadan kaldıran bir ölçülü kılma anlamı verir. İbn Atıyye, Beyzâvî, Semîn, Elmalılı ve Bursevî hafif biçimde denge anlamına imkân tanır; Study Quran her yöne çevirmeye imkân tanır."}]}
{"id":"82:7/q06","question":"فَعَدَلَكَ ne anlama gelir?","turns_on":"ʿadl'in anatomik dengeyi, özellikle insanın dik duruşunu, Allah'ın seçtiği biçimlere yöneltmeyi, içsel yetileri veya eksik ve mükemmel haller arasında geçişi mi ifade ettiği; iki okuyuş ve 8. ayet çeşitli açıklamaları etkiler.","positions":[{"id":"82:7/q06/p1","position":"Allah insan bedenini, özellikle karşılıklı uzuvlarını dengeli ve orantılı kıldı.","reasons":"Ahfeş ve Nehhâs iki biçimin bu anlamı paylaşabileceğini söyler; Nehhâs iki tarafta eşit sayıda kişinin öldürülmesi hakkında bir şiir aktarır. Taberî dik duruşu ekler. İbn Hâleveyh ve Mukātil, Vâhidî, Tabersî ve Elmalılı'nın aktardığı üzere, çift gözleri, kulakları, elleri ve ayakları belirtir; Semîn hiçbir el veya ayağın diğerinden uzun, hiçbir gözün diğerinden geniş olmadığını söyler. Vâhidî tek bir ayrışmamış biçim yerine farklı organları açıklar. Bursevî eşleşen kemikler, toplardamarlar, atardamarlar ve sinirler hakkında anatomi bilginlerini aktarır. Elmalılı 75:4'teki dengeli parmak uçlarıyla karşılaştırır, ancak bu okuyuşun tek başına insana özgü olanı belirtmediğini söyler. Beyzâvî de orantılı yapıdan, Bikāî ise dengeli mizaçtan söz eder."},{"id":"82:7/q06/p2","position":"Allah insanları kendilerine özgü insani bir biçimde dik ve güzel kıldı.","reasons":"Mukātil ve Atâ aracılığıyla İbn Abbas dik duruşu ve güzel görünüşü anlatır. İbn Kesîr bunu en güzel kıvam ve biçim diye niteler. Elmalılı, hayvanların eğri sırtlarının aksine İbn Abbas'ın düz sırt açıklamasını tercih eder; çünkü bu daha çok insana özgüdür ve biçimlendirmeden sonra gelmeye uygundur. Bikāî hafif okuyuşun biçim bozukluğundan dik duruşa çevirmeyi anlattığını söyler; Bursevî çirkin hayvan biçiminden ayrılmak için 95:4'ü aktarır."},{"id":"82:7/q06/p3","position":"Allah insanı dilediği herhangi bir biçime çevirdi veya yöneltti.","reasons":"İbn Kuteybe, Taberî, İbn Hâleveyh, Sa'lebî, Begavî ve Kurtubî güzel veya çirkin, uzun veya kısa gibi alternatifler verir; Taberî bir akrabaya benzemeyi kapsar, Nehhâs sağlık veya hastalığı ekler ve Ferrâ'nın açıklaması hafif okuyuşu 8. ayetle ilişkilendirir. Semîn bunu ʿudūl kökünden türetir; Study Quran Allah'ın insanları her yöne çevirebileceğini söyler. Ahfeş, kişiyi bu şekilde biçimlendirdiğini söyler. Cüşemî ve Kurtubî hafif okuyuşu aktaranları sayar."},{"id":"82:7/q06/p4","position":"Allah bedensel biçimi insani yetiler, akıl, düşünce, güç veya saadet yetileriyle dengeledi.","reasons":"Beyzâvî anatomik dengenin yanında saadete götüren yetileri verir. Vâhidî ve Elmalılı'nın aktardığı Ebû Ali el-Fârisî, başkalarında bulunmayan yetileri ve yaratılmışlar arasındaki üstünlüğü kapsar; Elmalılı 15:29 ve 17:70'i aktarır ve bunları ilahî cömertlik olarak niteler. Esed düşünsel ve ruhsal algının yanında bedensel ihtiyaçları ve duygusal dürtüleri kapsar. Study Quran iman veya itaatsizlik gibi içsel nitelikleri yahut kurtuluş ve azaba mahkûmiyet olarak anlaşılan saadet ve bedbahtlığı belirtir ve 11:105'i aktarır."},{"id":"82:7/q06/p5","position":"Allah insanı art arda eksik biçimlerden mükemmelliğe doğru çevirdi.","reasons":"Elmalılı bunu en iyi biçime doğru tekrar tekrar seçilmeyi anlatan muhtemel bir hafif okuyuş anlamı sayar."},{"id":"82:7/q06/p6","position":"Allah mükemmelleşmiş insanı daha aşağı bir hale çevirebilir.","reasons":"Elmalılı bu alternatifi cömertliğe aldanmama uyarısıyla ve ahiretle ilişkilendirerek 95:5'i aktarır."}]}

{"id":"82:6/q10","question":"al-Karim burada ne anlama gelir?","turns_on":"Açıklamalar cömertliğin farklı eylemlerini vurgular: af ve örtme, karşılıksız bağış, orantısız mükâfat veya genel ihsan örüntüsü.","positions":[{"id":"82:6/q10/p1","position":"Bağışlayan, affeden ve kusurları örten.","reasons":"İbn Kuteybe bağışlamayı asaletle ilişkilendirir; İbnü'l-Cevzî bağışlayıcı veya cömert anlamlarını aktarır. Kurtubî, Fudayl'ın “indirilmiş perdeler” ifadesini karim'in örten kimse anlamıyla ilişkilendirir."},{"id":"82:6/q10/p2","position":"Çıkar gözetmeden veren, gerekeni ve fazlasını sağlayıp kendisine borçlu olunanı talep etmeyen, sırf iyilik eden.","reasons":"Tabersî şu iki tanımı verir: kazanç sağlamayı veya zararı savuşturmayı amaçlamamak ve kendi hakkını istemeden yükümlülüğünün ötesinde vermek. Tabâtabâî de Allah'ın yarar veya karşılık gözetmediğini, haksızlığa tahammül ettiğini ve bilgisizlikten doğan günahları bağışladığını söyler."},{"id":"82:6/q10/p3","position":"Azı kabul edip çoğunu veren, hatta günahları iyiliklere dönüştüren.","reasons":"Tabersî kısa tanımı, ardından günahları iyiliklere dönüştürme şeklindeki daha güçlü işareti verir."},{"id":"82:6/q10/p4","position":"Gücü yettiğinde affeden, sözlerini yerine getiren, bolca veren, kendisine başvuranları koruyan ve onlara yumuşakça, doğrudan muamele eden.","reasons":"Bikāî'nin aktardığı Gazâlî, böyle birinin başkalarının başvuran kişiyi reddetmesine razı olmadığını, bütün alacaklarını tahsil etmeden öğüt verdiğini ve aracıya ihtiyaç duymadığını da söyler."},{"id":"82:6/q10/p5","position":"Lütufkâr ilahî cemal sıfatı.","reasons":"Kur'an Yolu, Allah'ın kullarına yönelik lütufkârlığını ifade eden adlar olarak karim ile rabb'i eşleştirir."}]}
{"id":"82:6/q11","question":"Rab neden al-Karim diye anılır ve O'nun cömertliği nasıl bir karşılık doğurmalıdır?","turns_on":"Sıfatın cömertliğe güvenmeyi mazeret olarak mı sunduğu, yoksa ahlaki kınamayı mı keskinleştirdiği; İbn Kesîr ve Elmalılı ilk çıkarımı açıkça reddeder.","positions":[{"id":"82:6/q11/p1","position":"O'nun cömertliği azarı ağırlaştırır ve şükre, saygıyla korkmaya, imana ve itaate yol açmalıdır.","reasons":"Beyzâvî, Bikāî, Bursevî ve Elmalılı, cömertliğin kötülük yapanları ihmal etmeyi veya itaat edenlerle etmeyenleri bir tutmayı gerektirdiğini reddeder; Bursevî ihmalin mağdurlara haksızlık olacağını ekler ve 15:49-50'yi aktarır. Bikāî, soylu bir iyilik sahibinin hilim sahibi ama heybetli olduğunu söyler. İbn Kesîr, cömertliğe çirkin eylemlerle karşılık verilmemesi gerektiğini söyler. Elmalılı, hikmetle birleşen cömertliğin “serbestçe günah işle” çıkarımını yanlış bir kıyas kıldığını söyler, 35:5 ile karşılaştırır ve müminlerdeki utanç ve pişmanlığı belirtir. Tabâtabâî, verenin karşılık beklemediği yerde nankörlüğün daha ağır olduğunu söyler. Ali'nin, hizmetkârların kötü edebinin efendinin terbiyesini yansıttığına ilişkin sözü ahlaki benzetmeyi destekler."},{"id":"82:6/q11/p2","position":"Sıfat, günahkârın Kerîm'in cömertliğinin kendisini aldattığı cevabını çağrıştırır.","reasons":"İşârî yorumcular ve Tabersî seçilen sıfatın bu cevabı ima ettiğini söyler; İbn Atıyye bunu günahkâr müminlere gösterilen iyilikle ilişkilendirir. Elmalılı uyarı bağlamının buna izin vermediğini söyler; İbn Kesîr çıkarımı zayıf bulur."}]}
{"id":"82:6/q12","question":"Nüzul sebebi rivayetlerinde Peygamber'e vuran suçluya ne oldu?","turns_on":"Rivayetler yalnızca cezanın gecikmesini belirtmeleri veya Peygamber'in hemen verdiği karşılığı ve serbest bırakmayı anlatmaları bakımından farklılaşır.","positions":[{"id":"82:6/q12/p1","position":"Peygamber'e vurdu ve hemen cezalandırılmadı; bu da ayetin nüzulüne yol açtı.","reasons":"Vâhidî bunu Abu al-Ashaddayn'e, Begavî ve İbn Kesîr ise Esved b. Şerîk'e bağlar. Elmalılı olayı aktarır, ancak adı kesinleştirmez."},{"id":"82:6/q12/p2","position":"Peygamber'e vurduktan sonra adam yere serildi, eman istedi, ona zarar vermeyeceğine söz verdi ve serbest bırakıldı.","reasons":"Bursevî, Zahrat al-Riyad'da başın tepesine indirilen darbeyi ve sonraki karşılaşmayı belirten bir rivayet aktarır."}]}
{"id":"82:6/q13","question":"Bu ayet dirilişteki hangi buluşmayı ve soruları akla getirir?","turns_on":"","positions":[{"id":"82:6/q13/p1","position":"Her kişi Allah'la tek başına karşılaşır ve kendisini neyin aldattığı, bilgisini nasıl kullandığı ve elçilere nasıl karşılık verdiği sorulur.","reasons":"İbn Mesud'un rivayeti Sa'lebî, Begavî, Tabersî ve Kurtubî'de yer alır; İbn Kesîr elçiler hakkındaki soruyu içeren bağlantılı bir hadisi aktarır."}]}
{"id":"82:6/q14","question":"İnsanı Allah'tan içsel olarak ne perdeler?","turns_on":"İçsel açıklamalar ya dikkati başka yöne çeken bir unsuru ya da ilahî korumayı terk etmeyi belirtir.","positions":[{"id":"82:6/q14/p1","position":"Allah dışındaki herhangi bir şeyin kalbe girmesi onu Allah'tan koparır.","reasons":"Tüsterî, müminin kalbinin kula en yakın olduğunu ve yabancı bir varlığın ilahî yumuşaklık ve cömertliğe rağmen perdeye dönüştüğünü söyler. Allah'ı kalple müşahede etmek kişiyi başka her şeyden uzaklaştırır."},{"id":"82:6/q14/p2","position":"Allah'ın korumasından bilgisizce ayrılmak kulu aldatır.","reasons":"Ömer b. Vâsıl ayeti okurken bu cevabı verir."}]}
{"id":"82:6/q15","question":"Kul bu hitaba karşılık Allah'la ilişkisini nasıl yaşamalıdır?","turns_on":"Notlar, davranışları dikkatle gözetme ve bağımlılığını kabul ederek dayanma şeklindeki birbirini tamamlayan uygulamaları anlatır.","positions":[{"id":"82:6/q15/p1","position":"Allah bilinciyle kalbi korumalı ve O'nun gözetimi altında amellerde sebat etmelidir.","reasons":"Tüsterî, kalbi Allah'a teslim etmenin O'nun uzuvları yönetip doğrultmasını sağladığını; kalbin tanıklığının uzuvların ne kadar özenle korunduğunu yansıttığını söyler. Yaratıcının nerede olurlarsa olsunlar yaratılmışlarla birlikte olduğunun bilincine çağırır."},{"id":"82:6/q15/p2","position":"Allah'ın rızasını aramalı, ihtiyaçlarını O'na sunmalı ve kendi zayıflığını kabul ederek O'na dayanmalıdır.","reasons":"Tüsterî, Allah'ın hilmiyle hoşnutluk verdiğini söyler, O'nun kapısında kalmaya çağırır ve insanın bilgisizliği, zayıflığı ve acizliğini Allah'ın ilmi, gücü ve kudretiyle karşılaştırır; böyle bir dayanma havayı, açık alanı, yeri ve göğü birbirine eşit kılar."}]}
{"id":"82:6/q16","question":"Allah'a atfedilen bir ünlem şaşkınlık ifade edebilir mi?","turns_on":"Şaşkınlığın gizli bir sebebi bilmemeyi gerektirip gerektirmediği ve ilahî dilin dinleyicilerin deneyimine nasıl gönderme yapabileceği.","positions":[{"id":"82:6/q16/p1","position":"Gizli bir sebep veya bir şeyin Allah'ı yücelttiğini ima ediyorsa Allah karşısında gerçek anlamda şaşkınlık kabul edilmez.","reasons":"Burhân, ezelî ilahî sıfatlardan hareket eden bu itirazı aktarır."},{"id":"82:6/q16/p2","position":"Allah'ın büyüklüğünün bir sebebi olduğunu ima etmeden yüceltme amacıyla hayret bildiren dile izin verilir.","reasons":"Burhân, ibadet edenlerin Allah'ın kudretine inanmasının buna imkân verdiği görüşünü aktarır ve O'nun uzağı yaklaştırması hakkında bir şiir nakleder. Başka âlimler, şaşkınlığın başka bir fail gerektirmeden meselenin kendisini yücelttiğini söyler; bir sebep yalnızca bize gizli olabilir."},{"id":"82:6/q16/p3","position":"İlahî ünlem, dinleyicilerin bakış açısından hayrete değer olan ve Allah'ın bildiği şeyi anlatır.","reasons":"Burhân bu görüşü tercih eder; âlimler de ilahî ünlem, dua ve umudu benzer biçimde dinleyici açısından yorumlar. Sîbeveyhi, 20:44'ü Mûsâ ve Hârûn'un kendi umutlarına göre hareket etmesi olarak açıklar; Ibn al-Da'i bu açıklamayı över."}]}
{"id":"82:6/q17","question":"Bu uyarı çevresindeki pasajla nasıl uyuşur?","turns_on":"Kaynaklar farklı bağlantıları vurgular: dirilişten inkâra giden dizi, yaratılıştan çıkarılan kanıt veya başka bir yerdeki paralel uyarı.","positions":[{"id":"82:6/q17/p1","position":"Dirilişin ilanı uyarıya ve akla dayalı bir çağrıya götürür; ardından kişinin hesabı inkârı açığa çıkarılır.","reasons":"Elmalılı, pasajın dirilişten düşünmeye geçtiğini söyler. Tabâtabâî 82:9'u inkârcıyı belirleyen ayet olarak okur; Esed bunun cevabı verdiğini söyler ve 8:25'teki geniş kapsamlı fitne tehlikesiyle karşılaştırır. Study Quran 82:6–12'nin ahiret günü hakkında kınayıp uyardığını söyler. Islâhî, mevcut mühletin ıslah için zaman tanıdığını, kayıt meleklerinin ise hiçbir şeyin gizli kalmamasını sağladığını söyler."},{"id":"82:6/q17/p2","position":"İnsanların yaratılması ve biçimlendirilmesi Allah'ın kudretini, hikmetini, merhametini ve adaletini göstererek dirilişi ve hesabı kesin ve amaçlı kılar.","reasons":"Islâhî, yeniden yaratmanın ilk yaratılıştan daha zor olamayacağını ve insanın biçimlendirilmesindeki işaretlerin ödül ve ceza gününü gerektirdiğini savunur. Tabâtabâî rablik ve cömertliği nankörlüğe karşı delil sayar."},{"id":"82:6/q17/p3","position":"Uyarı, Allah hakkında aldanmama yönündeki Kur'anî ikazı tekrarlar.","reasons":"Elmalılı öğretiyi 35:5 ile özdeş sayar; Islâhî başka bir yerde bir uyarıyı açıkça 82:6 ile ilişkilendirir."}]}
{"id":"82:6/q18","question":"İnfitâr, Tekvîr ile nasıl ilişkilidir?","turns_on":"","positions":[{"id":"82:6/q18/p1","position":"Biçim, üslup, anlam ve başlangıçtaki felaket bakımından birbirinin karşılığıdırlar, ancak İnfitâr başlıca yaratılıştan ve ilahî adaletten kanıt getirir.","reasons":"Islâhî her ikisinin de kibirli zengin Kureyşlilere hitap ettiğini söyler. Tekvîr Kur'an'ın sahihliği, kaynağı, vahyedilmesi ve taşıyıcısından kanıt getirir; inkârcılar şafağı geceden ayıramaz. İnfitâr ise Allah'ın yaratma kudreti, hikmeti, adaleti ve merhametinden yaklaşan hesaba kanıt getirir."}]}
{"id":"82:6/q19","question":"Kur'an başka nerede bir ayete “Ey insan” diye başlar?","turns_on":"","positions":[{"id":"82:6/q19/p1","position":"İki ayet böyle başlar: cömert Rab hakkındaki bu soru ve Rabbe doğru çabalamayı anlatan 84:6.","reasons":"Burhân bu iki başlangıcı sayar; İbn Kuteybe de tekil hitabın topluluğu kapsamasını ele alırken 84:6'yı aktarır."}]}
{"id":"82:6/q20","question":"Sûre ne zaman indirildi?","turns_on":"Aktarılan otoriteler, sûrenin Mekke'de erken mi yoksa geç dönemde mi indirildiği konusunda farklı görüştedir.","positions":[{"id":"82:6/q20/p1","position":"Bazı otoriteler onu Mekke döneminin başlarına yerleştirir.","reasons":"Esed bu tarihlendirmeyi aktarır."},{"id":"82:6/q20/p2","position":"Başkaları, onun Mekke'deki son vahiyler arasında olmasını daha muhtemel görür.","reasons":"Esed bu geç tarihlendirmeyi daha muhtemel olarak aktarır."}]}
{"id":"82:7/q01","question":"ٱلَّذِى dilbilgisi bakımından önceki ayete nasıl bağlanır?","turns_on":"İlgi zamirli ifadenin önceki yapıyı mı sürdürdüğü, yoksa bağımsız bir yapı mı başlattığı.","positions":[{"id":"82:7/q01/p1","position":"Önceki ifadeyi bedel, atf-ı beyan veya sıfat olarak izler.","reasons":"Semîn bu üç bağlantılı çözümlemeyi sıralar."},{"id":"82:7/q01/p2","position":"Merfû veya mansûb durumda bağımsızdır.","reasons":"Semîn bağımsız kullanım için her iki irap ihtimalini de verir."}]}
{"id":"82:7/q02","question":"خَلَقَكَ Allah'ın ne yaptığını söyler?","turns_on":"","positions":[{"id":"82:7/q02/p1","position":"Allah, insanı ilk olarak yoktan veya onu biçimlendirmeden önce bir damladan var etti.","reasons":"Vâhidî ve Tabersî bir damladan işiten, gören bir kişiye dönüşmeyi anlatır; Kurtubî bunun rahimde olduğunu belirtir ve çift uzuvları sayar. Elmalılı yaratmanın biçim verme, dengeleme, şekillendirme ve birleştirmeden önce geldiğini söyler; Islâhî yaratma sözcüklerinde ilk ve son aşamaları görür. Mukātil yaratma, ölçülü kılma ve dik hale getirme dizisini belirtir."}]}
{"id":"82:7/q03","question":"فَسَوَّىٰكَ neyi anlatır?","turns_on":"Biçimlendirmenin bedensel işlev, aşamalı olgunlaşma, ölçüde denklik veya her kişinin kendine özgü donanımı anlamlarından hangisini taşıdığı.","positions":[{"id":"82:7/q03/p1","position":"Allah, organları ve yetileri işlevlerine uygun, sağlıklı ve düzenli bir beden şekillendirdi.","reasons":"Vâhidî ve Tabersî embriyonik kökenin ardından işitme ve görmeyi belirtir. Beyzâvî işlevlerine hazır, sağlıklı ve ölçülü organlardan söz eder; Bursevî kavrama, yürüme ve görmeyi sayar. Bikāî her parçanın amaçlanan yararını, mizacını ve yapısını vurgular. Study Quran parçaları ve yetileri sağlıklı ve işlevsel olarak niteler; Kuşeyrî bu uygunluğu hikmetli sayar ve güzellik ile boydaki farklılıkları belirtir."},{"id":"82:7/q03/p2","position":"Allah insanı olgunlaşıp ruhu almaya elverişli hale gelene kadar aşamalar boyunca geliştirdi.","reasons":"Elmalılı bedenin, uzuvların ve yetilerin mükemmelleştirilip düzenlenmesini kapsar ve 18:37'yi aktarır; Islâhî sözcüklerin yapma veya taslak çizme ve yaratmadan mükemmelleştirmeye ilerlediğini, ilk ve son aşamalara işaret ettiğini söyler."},{"id":"82:7/q03/p3","position":"Taswiya, bir şeyi dıştan veya içten denk bir ölçüye getirmek demektir.","reasons":"Cüşemî ölçü belirleme anlamını verir ve hem bedensel biçime hem iç karaktere imkân tanır."},{"id":"82:7/q03/p4","position":"Allah her kişiyi o kişinin hayatına ve çevresine uygun nitelik ve yetilerle donattı.","reasons":"Esed yalnızca genel bir bedensel kalıbı değil, kişiye özgü uygunluğu belirtir."}]}
{"id":"82:7/q04","question":"Bitişik kāf sesleri idgam edilebilir mi?","turns_on":"","positions":[{"id":"82:7/q04/p1","position":"Belirtilen hareke koşullarına göre bitişik özdeş kāf ünsüzleri idgam edilebilir veya ayrı bırakılabilir.","reasons":"Ahfeş idgamı açıklar ve durumları birinci veya ikinci harfin harekeli olmasına göre ayırır."}]}
{"id":"82:7/q05","question":"فَعَدَلَكَ nasıl okunur?","turns_on":"Dāl'in şeddeli mi yoksa hafif mi olduğu ve sonraki ayetteki fī'nin yöneltme anlamına bağlanıp bağlanamayacağı; her iki okuyuş da aktarılmıştır.","positions":[{"id":"82:7/q05/p1","position":"Şeddeli dāl ile, fa-ʿaddalaka, II. bâb olarak okunur.","reasons":"Taberî Medineli, Mekkeli, Şamlı ve Basralı kıraat imamlarını sayar; Nehhâs aynı görüştedir. Cüşemî İbn Kesîr, Ebû Amr, İbn Âmir ve Ya'kūb'u sayar. Sa'lebî, Begavî, Kurtubî, İbn Atıyye, Semîn, İbnü'l-Cezerî ve Dürr diğer kıraat imamlarının veya çoğunluğun bu okuyuşunu aktarır; İbn Atıyye, ravilerin Peygamber'in hilali gördüğünde söylediği sözde dāl'i şeddeli okuduğu konusunda hemfikir olduğunu söyler; Dürr, Hâkim'in sahih saydığı, Peygamber'in şeddeli okuyuşuna ilişkin Ebû Hüreyre rivayetini aktarır. QIRAAT-ER kapsamlı düzenleme, düzeltme veya orantılı ayarlamayı II. bâbın anlamları olarak belirtir. Ahfeş ve İbn Hâleveyh şeddeli biçimin anlamını açıklar; Zeccâc her iki telaffuzu aktarır. Taberî ikisini de sahih kabul eder, ancak Arapçada düzenleme anlamı fī ile daha kolay birleştiği için şeddeli biçimi tercih eder. Sa'lebî'ye göre Ferrâ ve Ebû Ubeyd 95:4'ü aktararak bunu tercih eder; Vâhidî onların tercihini ve Ferrâ'nın yöneltme anlamıyla fī kullanımına itirazını aktarır. Cüşemî de Ferrâ'nın tercihini aktarır. Kurtubî, Ebû Ubeyd ve Ebû Hâtim'in 95:4 ile bu biçimi seçtiğini söyler. Study Quran, 8. ayet 7. ayeti sürdürüyorsa bu biçimi tercih eder."},{"id":"82:7/q05/p2","position":"Hafif dāl ile, fa-ʿadalaka, I. bâb olarak okunur.","reasons":"Ahfeş ve İbn Kuteybe hafif biçimi aktarır. Taberî, Nehhâs, Sa'lebî, Vâhidî, Begavî, İbn Atıyye, Tabersî, Semîn, İbnü'l-Cezerî ve Kurtubî Kûfeli kıraat imamlarını belirtir; Cüşemî ayrıca Ebû Cafer, Âsım, Hamza ve Kisâî'yi sayar. Taberî bu yerleşik okuyuşu da kabul eder. Nehhâs, Ferrâ'nın dilbilgisel itirazını reddeder: fī, rakkabaka ile kurulan sonraki cümleyi başlatır. Vâhidî'nin aktardığı Ebû Ali hafif biçime itirazı ortadan kaldıran bir ölçülü kılma anlamı verir. İbn Atıyye, Beyzâvî, Semîn, Elmalılı ve Bursevî hafif biçimde denge anlamına imkân tanır; Study Quran her yöne çevirmeye imkân tanır."}]}
{"id":"82:7/q06","question":"فَعَدَلَكَ ne anlama gelir?","turns_on":"ʿadl'in anatomik dengeyi, özellikle insanın dik duruşunu, Allah'ın seçtiği biçimlere yöneltmeyi, içsel yetileri veya eksik ve mükemmel haller arasında geçişi mi ifade ettiği; iki okuyuş ve 8. ayet çeşitli açıklamaları etkiler.","positions":[{"id":"82:7/q06/p1","position":"Allah insan bedenini, özellikle karşılıklı uzuvlarını dengeli ve orantılı kıldı.","reasons":"Ahfeş ve Nehhâs iki biçimin bu anlamı paylaşabileceğini söyler; Nehhâs iki tarafta eşit sayıda kişinin öldürülmesi hakkında bir şiir aktarır. Taberî dik duruşu ekler. İbn Hâleveyh ve Mukātil, Vâhidî, Tabersî ve Elmalılı'nın aktardığı üzere, çift gözleri, kulakları, elleri ve ayakları belirtir; Semîn hiçbir el veya ayağın diğerinden uzun, hiçbir gözün diğerinden geniş olmadığını söyler. Vâhidî tek bir ayrışmamış biçim yerine farklı organları açıklar. Bursevî eşleşen kemikler, toplardamarlar, atardamarlar ve sinirler hakkında anatomi bilginlerini aktarır. Elmalılı 75:4'teki dengeli parmak uçlarıyla karşılaştırır, ancak bu okuyuşun tek başına insana özgü olanı belirtmediğini söyler. Beyzâvî de orantılı yapıdan, Bikāî ise dengeli mizaçtan söz eder."},{"id":"82:7/q06/p2","position":"Allah insanları kendilerine özgü insani bir biçimde dik ve güzel kıldı.","reasons":"Mukātil ve Atâ aracılığıyla İbn Abbas dik duruşu ve güzel görünüşü anlatır. İbn Kesîr bunu en güzel kıvam ve biçim diye niteler. Elmalılı, hayvanların eğri sırtlarının aksine İbn Abbas'ın düz sırt açıklamasını tercih eder; çünkü bu daha çok insana özgüdür ve biçimlendirmeden sonra gelmeye uygundur. Bikāî hafif okuyuşun biçim bozukluğundan dik duruşa çevirmeyi anlattığını söyler; Bursevî çirkin hayvan biçiminden ayrılmak için 95:4'ü aktarır."},{"id":"82:7/q06/p3","position":"Allah insanı dilediği herhangi bir biçime çevirdi veya yöneltti.","reasons":"İbn Kuteybe, Taberî, İbn Hâleveyh, Sa'lebî, Begavî ve Kurtubî güzel veya çirkin, uzun veya kısa gibi alternatifler verir; Taberî bir akrabaya benzemeyi kapsar, Nehhâs sağlık veya hastalığı ekler ve Ferrâ'nın açıklaması hafif okuyuşu 8. ayetle ilişkilendirir. Semîn bunu ʿudūl kökünden türetir; Study Quran Allah'ın insanları her yöne çevirebileceğini söyler. Ahfeş, kişiyi bu şekilde biçimlendirdiğini söyler. Cüşemî ve Kurtubî hafif okuyuşu aktaranları sayar."},{"id":"82:7/q06/p4","position":"Allah bedensel biçimi insani yetiler, akıl, düşünce, güç veya saadet yetileriyle dengeledi.","reasons":"Beyzâvî anatomik dengenin yanında saadete götüren yetileri verir. Vâhidî ve Elmalılı'nın aktardığı Ebû Ali el-Fârisî, başkalarında bulunmayan yetileri ve yaratılmışlar arasındaki üstünlüğü kapsar; Elmalılı 15:29 ve 17:70'i aktarır ve bunları ilahî cömertlik olarak niteler. Esed düşünsel ve ruhsal algının yanında bedensel ihtiyaçları ve duygusal dürtüleri kapsar. Study Quran iman veya itaatsizlik gibi içsel nitelikleri yahut kurtuluş ve azaba mahkûmiyet olarak anlaşılan saadet ve bedbahtlığı belirtir ve 11:105'i aktarır."},{"id":"82:7/q06/p5","position":"Allah insanı art arda eksik biçimlerden mükemmelliğe doğru çevirdi.","reasons":"Elmalılı bunu en iyi biçime doğru tekrar tekrar seçilmeyi anlatan muhtemel bir hafif okuyuş anlamı sayar."},{"id":"82:7/q06/p6","position":"Allah mükemmelleşmiş insanı daha aşağı bir hale çevirebilir.","reasons":"Elmalılı bu alternatifi cömertliğe aldanmama uyarısıyla ve ahiretle ilişkilendirerek 95:5'i aktarır."}]}
{"id":"82:7/q07","question":"8. ayetteki فِيٓ أَىِّ صُورَةٍ, فَعَدَلَكَ ile nasıl ilişkilidir?","turns_on":"fī'nin ʿadalaka'ya mı yoksa sonraki rakkabaka'ya mı bağlandığı ve yöneltme anlamının ilā gerektirip gerektirmediği.","positions":[{"id":"82:7/q07/p1","position":"Düzenleme fiilini sürdürerek şeddeli okuyuşu destekler.","reasons":"Taberî, Arapçada düzenleme anlamının fī ile daha doğal söylenmesi nedeniyle şeddeli okuyuşu tercih eder. Nehhâs ve Vâhidî'nin aktardığı Ferrâ, yöneltmenin fī değil ilā aldığını söyler; Vâhidî 8. ayetin hafif fiile bağlanmasının zayıf olduğunu belirtir. Study Quran, 8. ayet 7. ayeti sürdürüyorsa şeddeli biçimin dilbilgisi bakımından daha iyi olduğunu söyler."},{"id":"82:7/q07/p2","position":"Cümle فعدلك ifadesinde biter; fī sonraki ركبك fiiline aittir.","reasons":"Nehhâs, Ferrâ'nın hafif okuyuşa yönelik itirazını reddetmek için bu bağlantıyı kullanır."}]}
{"id":"82:7/q08","question":"Rahimde biçimlenmeye ilişkin hangi anlatı bu ayetle ilişkilendirilir?","turns_on":"","positions":[{"id":"82:7/q08/p1","position":"Bir meleğin kişinin toprağını embriyoyla karıştırmasından önce üç kırk günlük aşama vardır.","reasons":"İbn Hâleveyh anlatıyı ilahî biçimlendirmeyle ilişkilendirir ve 3:6 ile 23:14'ü aktarır; eldeki alıntı anlatının ortasında kesilir."}]}
{"id":"82:7/q09","question":"Peygamber'e ait hangi azarlama bu ayetin dilini kullanır?","turns_on":"","positions":[{"id":"82:7/q09/p1","position":"Allah, Âdemoğlunu yaratıp biçimlendirdikten ve doğrulttuktan sonra onu kibir ve mal yığma yüzünden azarlar.","reasons":"Busr b. Cehhâş Peygamber'in anlatımını aktarır: kişi malını esirger ve ancak ölüm köprücük kemiklerine ulaştığında sadaka vereceğine söz verir. Mizzî, Yahyâ b. Hamza, Sevr b. Yezîd ve Abdurrahman b. Meysere üzerinden gelen destekleyici bir rivayet yolunu belirtir."}]}
{"id":"82:7/q10","question":"İnsanın yaratılması ve düzenlenmesi için hangi içsel yorumlar verilir?","turns_on":"Aktarılan iki içsel açıklama, bilgi ve imanı veya insanlığın diğer yaratılmışlarla ilişkisini vurgular.","positions":[{"id":"82:7/q10/p1","position":"Allah insan biçimini bilgiyle mükemmelleştirdi ve imanla düzenledi.","reasons":"Bursevî Cüneyd'in ifadesini aktarır."},{"id":"82:7/q10/p2","position":"Allah insanı yarattı ve onu yaratılmışların hizmetine vermeden bütün yaratılmışları onun hizmetine verdi.","reasons":"Bursevî Zünnûn'un ifadesini aktarır."}]}
{"id":"82:7/q11","question":"İnsanın yaratılışı Allah'ın cömertliğini ve rabliğini nasıl temellendirir?","turns_on":"","positions":[{"id":"82:7/q11/p1","position":"İnsanı yaratıp uygun biçime sokmak Allah'ın rabliğini ve cömertliğini gösterir; varoluşun kendisi ilk nimettir.","reasons":"Beyzâvî bu nitelemeyi rabliğin doğrulanması ve cömertliğin tezahürü sayar. Bursevî varoluşun yokluktan daha iyi olduğunu söyler; Elmalılı varoluşu bütün nimetlerin temeli sayar ve 15:29 ile 17:70 ışığında aklı ve üstünlüğü bağış olarak niteler."}]}
{"id":"82:7/q12","question":"İnsanın biçimlendirilmesi diriliş ve hesap hakkında neyi gerektirir?","turns_on":"","positions":[{"id":"82:7/q12/p1","position":"İnsanları ilk kez yaratan ve biçimlendiren onları yeniden yaratabilir ve hesaba çekecektir.","reasons":"Beyzâvî ve Bursevî ilk yaratılıştan yeniden yaratmayı çıkarır. Islâhî ilk yaratılışın dirilişi zor olmaktan çıkardığını ve insanın biçimlendirilmesindeki kudret, yaratıcılık, ihtimam, hikmet, merhamet ve adaletin amaçlı bir hayatı ve yaklaşan ödül-ceza gününü gösterdiğini söyler. Elmalılı'nın mükemmellikten muhtemel düşüş yorumu 95:5 ile ahiret hakkında uyarır."}]}
{"id":"82:7/q13","question":"İnsanın yaratılışı nasıl bir karşılık gerektirir?","turns_on":"Vurgunun ilahî biçimlendirmeden doğan yükümlülükte mi, yoksa hesap öncesindeki fırsat ve gözetimde mi olduğu.","positions":[{"id":"82:7/q13/p1","position":"Kibir, nankörlük veya inkâr yerine şükür ve saygıyla korkma gerektirir.","reasons":"Bikāî ölçülü kılanın biçimi bozabileceğini veya cezalandırabileceğini söyler. Kur'an Yolu, bedensel ve zihinsel yetilerin ve bütün nimetlerin isyanı ve inkârı nankörlük kıldığını söyler. İbn Kesîr'in Peygamber'den aktardığı rivayet, Allah'ın bağışlarından sonra kibri ve mal yığmayı azarlar. Islâhî insanın biçimlendirilmesinin amaç ve sorumluluğu ortaya koyduğunu, sınavı yerine getirmeyi reddetmenin cezayı hak ettiğini söyler."},{"id":"82:7/q13/p2","position":"Allah'ın şu an tanıdığı mühlet, kötülük yapanlara hesap öncesinde ıslah olmaları için zaman verir.","reasons":"Islâhî bu fırsattan sonra reddetmenin mazeret bırakmadığını söyler; görevlendirilmiş melekler bu arada her sözü ve eylemi kaydeder, dolayısıyla gecikme hiçbir şeyi gizlemez."}]}
{"id":"82:7/q14","question":"İnsanın dengeli yaratılışı insan tabiatı ve mertebesi hakkında neyi gerektirir?","turns_on":"Çıkarılan anlamın uyumlu insan tabiatı mı, olağanüstü yetiler mi, yoksa halifelik görevi mi olduğu.","positions":[{"id":"82:7/q14/p1","position":"Bedensel dürtüler ile düşünsel veya ruhsal algı, ilahî iradeyle amaçlanmış insan tabiatında bir arada bulunur.","reasons":"Esed bedensel ihtiyaçları ve duygusal dürtüleri düşünsel ve ruhsal algılarla birlikte ele alır ve beden ile ruh arasında içkin bir ahlaki çatışma olmadığı sonucuna varır."},{"id":"82:7/q14/p2","position":"İnsanın aklı, düşüncesi, gücü ve güzel biçimi diğer yaratılmışlardan üstünlüğünü gösterir.","reasons":"Elmalılı Ebû Ali el-Fârisî'nin açıklamasını aktarır ve 15:29 ile 17:70'i kaynak gösterir; Vâhidî de el-Fârisî'nin kendine özgü yetileri bulunan, incelikle ölçülü kılınmış insan açıklamasını aktarır."},{"id":"82:7/q14/p3","position":"İnsanlığın yaratılmışlar arasındaki orta konumu halifeliğe ve orta ümmete uygundur.","reasons":"Islâhî bu görevin yerine getirilmesini cennetin ebedî hükümranlığıyla ilişkilendirir ve 95:4'ü aktarır."}]}
{"id":"82:7/q15","question":"Bu ayet, Tekvîr'le karşılaştırıldığında İnfitâr'ın savına nasıl hizmet eder?","turns_on":"","positions":[{"id":"82:7/q15/p1","position":"İnfitâr, insanın yaratılışındaki Allah'ın yaratıcılığından, kudretinden, hikmetinden, adaletinden ve merhametinden hesaba kanıt getirir.","reasons":"Islâhî, Tekvîr'in Kur'an'ın sahihliğinden, kaynağından, vahyedilmesinden ve taşıyıcısından hareket eden akıl yürütmesini İnfitâr'ın insanın biçimlendirilmesine ilişkin işaretleriyle karşılaştırır. Biçim, üslup, anlamlar ve başlangıçtaki büyük felaket bakımından iki sûreyi birbirinin karşılığı sayar; her ikisi de binalarına güvenen ve uyarıları görmezden gelen zengin, kibirli Kureyşlilere hitap eder. Tekvîr'in Kur'anî kanıtını reddedenlerin parlak şafağı karanlık geceden ayıramadığını söyler."}]}
{"id":"82:7/q16","question":"Bu ayetin bulunduğu sûre ne zaman indirildi?","turns_on":"Sûrenin Mekke dönemi içindeki tarihlendirilmesi; not, belirleyici özel bir kanıt vermez.","positions":[{"id":"82:7/q16/p1","position":"Mekke döneminin başlarında.","reasons":"Esed bazı otoritelerin bu tarihlendirmesini aktarır."},{"id":"82:7/q16/p2","position":"Daha büyük olasılıkla Mekke'deki son vahiyler grubunda.","reasons":"Esed geç tarihlendirmeyi daha muhtemel görüş olarak aktarır."}]}
{"id":"82:7/q17","question":"Tefsirde örtülen ve bağışlanan günahlara ilişkin hangi hadis yer alır?","turns_on":"","positions":[{"id":"82:7/q17/p1","position":"Allah mümini yakınına alır, onu örter, günahlarını itiraf ettirir, ardından hayattayken onları örttüğünü ve bugün bağışladığını söyler.","reasons":"Bursevî bunu sahih bir hadis olarak aktarır; mümin bağışlanma ilanından önce helak olmaktan korkar."}]}
